@dataclass
class SecopsSecurityProfile:
    user_id: int
    risk_score: float = 0.0
    request_history: deque = field(default_factory=lambda: deque(maxlen=20))
    command_history: deque = field(default_factory=lambda: deque(maxlen=10))
    last_ip: Optional[str] = None
    is_shadow_banned: bool = False
    created_at: float = field(default_factory=time.time)
    last_activity_time: float = field(default_factory=time.time)
    alert_dispatched: bool = False


class AdvancedBotSecurityEngine:
    def __init__(
        self,
        min_human_interval_sec: float = 0.35,
        tarpit_threshold: float = 50.0,
        shadow_ban_threshold: float = 85.0,
        decay_rate_per_minute: float = 5.0
    ):
        self.min_human_interval = min_human_interval_sec
        self.tarpit_threshold = tarpit_threshold
        self.shadow_ban_threshold = shadow_ban_threshold
        self.decay_rate_per_minute = decay_rate_per_minute
        self.profiles: Dict[int, SecopsSecurityProfile] = defaultdict(lambda: SecopsSecurityProfile(user_id=0))
        self.total_inspected_requests: int = 0
        self.tarpit_event_count: int = 0
        self.shadow_ban_event_count: int = 0
        self.probes_detected_count: int = 0

        self.malicious_ips: Set[str] = {
            "198.51.100.24", "203.0.113.50", "192.0.2.100", "185.220.101.5", "185.220.101.7"
        }
        self.suspicious_probes: Set[str] = {
            "/admin_debug", "/root", "/dump_db", "/shell", "/exec",
            "../../", "../", "etc/passwd", "select *", "union select",
            "{{", "${jndi:", "<script>", "benchmark(", "sleep("
        }

    def evaluate_timing_heuristics(self, profile: SecopsSecurityProfile, text_input: str) -> float:
        now = time.time()
        score_increase = 0.0
        elapsed = now - profile.last_activity_time
        if elapsed > 60:
            decay = (elapsed / 60.0) * self.decay_rate_per_minute
            profile.risk_score = max(0.0, profile.risk_score - decay)
            profile.last_activity_time = now

        if len(profile.request_history) > 0:
            delta = now - profile.request_history[-1]
            if delta < self.min_human_interval:
                score_increase += 30.0
                logger.warning(f"Kullanıcı {profile.user_id}: Aşırı hızlı istek ({delta*1000:.1f}ms < {self.min_human_interval*1000}ms)")
            elif delta < 0.70:
                score_increase += 8.0

        if len(profile.request_history) >= 6:
            intervals = [
                profile.request_history[i] - profile.request_history[i - 1]
                for i in range(1, len(profile.request_history))
            ]
            variance = max(intervals) - min(intervals)
            if variance < 0.04:
                score_increase += 35.0
                logger.warning(f"Kullanıcı {profile.user_id}: Robotik sabit aralıklı döngü tespit edildi (Varyans: {variance:.4f}s)")

        clean_input = text_input.lower()
        for probe in self.suspicious_probes:
            if probe in clean_input:
                score_increase += 45.0
                logger.warning(f"Kullanıcı {profile.user_id}: Şüpheli prob/tuzak girdisi denendi -> '{probe}'")
                break

        profile.request_history.append(now)
        profile.command_history.append(text_input[:50])
        return score_increase

    async def check_threat_intelligence(self, ip_address: Optional[str]) -> Tuple[float, Dict[str, str]]:
        if not ip_address:
            return 0.0, {}
        risk = 0.0
        meta = {}
        if ip_address in self.malicious_ips:
            risk += 40.0
            meta["threat_reputation"] = "KNOWN_MALICIOUS_IP"
            logger.warning(f"Zararlı IP eşleşmesi: {ip_address}")
        return risk, meta

    async def process_security_pipeline(
        self,
        bot_inst: Bot,
        user_id: int,
        user_name: str,
        command_text: str,
        ip_address: Optional[str] = None
    ) -> Tuple[bool, Optional[str]]:
        profile = self.profiles[user_id]
        profile.user_id = user_id
        profile.last_ip = ip_address
        self.total_inspected_requests += 1

        heur_score = self.evaluate_timing_heuristics(profile, command_text)
        if heur_score >= 40.0:
            self.probes_detected_count += 1
            profile.risk_score += heur_score

        intel_risk, intel_meta = await self.check_threat_intelligence(ip_address)
        profile.risk_score += intel_risk

        clean_cmd = command_text.lower()
        if intel_risk > 0 and any(p in clean_cmd for p in self.suspicious_probes):
            profile.risk_score = max(profile.risk_score, self.shadow_ban_threshold + 10.0)
            logger.critical(f"Kullanıcı {user_id}: Şüpheli Ağ + Tuzak Komut Korelasyonu tespit edildi!")

        if profile.risk_score >= self.tarpit_threshold:
            self.tarpit_event_count += 1
            excess = profile.risk_score - self.tarpit_threshold
            delay_sec = min(5.0, 1.0 + (excess * 0.12))
            logger.info(f"Tarpit uygulandı: Kullanıcı {user_id}, {delay_sec:.2f}s geciktiriliyor...")
            await asyncio.sleep(delay_sec)

        if profile.risk_score >= self.shadow_ban_threshold:
            self.shadow_ban_event_count += 1
            if not profile.alert_dispatched:
                profile.alert_dispatched = True
                profile.is_shadow_banned = True
                asyncio.create_task(alert_admins_security_breach(
                    bot=bot_inst,
                    user_id=user_id,
                    user_name=user_name,
                    event_title="🚨 SHADOW BAN / SESSİZ GÖZLEM DEVREDE",
                    details=(
                        f"Kritik Anomali Skoru: %{profile.risk_score:.1f}\n"
                        f"Kaynak IP: {ip_address or 'Bilinmiyor'}\n"
                        f"Tetikleyen Komut: {command_text[:60]}\n"
                        f"İstihbarat Notu: {intel_meta.get('threat_reputation', 'Heuristik / Fuzzer Analizi')}"
                    )
                ))
            fake_resp = "⚠️ Sistem şu anda yoğun istek nedeniyle geçici olarak yanıt veremiyor. Lütfen birkaç dakika sonra tekrar deneyiniz."
            return False, fake_resp

        return True, None

