        lbl_s = get_text("lbl_subject", lang)
        lbl_cl = get_text("lbl_class", lang)
        lbl_no = get_text("lbl_number", lang)
        lbl_st = get_text("lbl_role_student", lang)

        extra = ""
        if user.role == "parent" and user.current_child_id:
            st = await session.get(Student, user.current_child_id)
            if st: extra = f"🧑‍🎓 <b>{lbl_st}:</b> {escape_html(st.full_name)} ({escape_html(st.class_name)})\n"
        elif user.role == "student":
            st = (await session.execute(select(Student).where(Student.student_telegram_id == user.telegram_id))).scalar_one_or_none()
            if st: extra = f"🏫 <b>{lbl_cl}:</b> {escape_html(st.class_name)} • <b>{lbl_no}:</b> <code>{escape_html(st.student_number)}</code>\n"
        elif user.role == "teacher":
            tch = (await session.execute(select(Teacher).where(Teacher.telegram_id == user.telegram_id))).scalar_one_or_none()
            if tch: extra = f"📚 <b>{lbl_s}:</b> {escape_html(tch.subject)}\n"

        p_title = get_text("uc_card_title", lang)
        lbl_r = get_text("lbl_role", lang)
        lbl_user = get_text("lbl_role_guest", lang)
        lbl_phn = {"tr": "Telefon", "ru": "Телефон", "uz": "Telefon", "en": "Phone"}.get(lang, "Phone")
        lbl_lng = {"tr": "Dil", "ru": "Язык", "uz": "Til", "en": "Language"}.get(lang, "Language")
        lbl_none = {"tr": "Kayıtlı Değil", "ru": "Не указан", "uz": "Kiritilmagan", "en": "Not provided"}.get(lang, "Not provided")
        phn_str = user.phone if user.phone else lbl_none
        usr_tag = f" (@{user.username})" if user.username else ""

        text = (
            f"<b>{p_title}</b>\n"
            "────────────────────\n"
            f"👤 <b>{escape_html(user.full_name or lbl_user)}</b>{usr_tag}\n"
            f"🆔 <code>{user.telegram_id}</code> • <b>{lbl_r}:</b> {role_label}\n"
            "────────────────────\n"
            f"📱 <b>{lbl_phn}:</b> <code>{escape_html(phn_str)}</code>\n"
            f"🌐 <b>{lbl_lng}:</b> {user.language.upper()}\n"
        )
        if extra:
            text += "────────────────────\n" + extra
        text += "────────────────────"
        await safe_edit_or_answer(message, text, parse_mode="HTML")

