async def cb_cancel_action(query: CallbackQuery, state: FSMContext | None = None):
    if state:
        try:
            await state.clear()
        except Exception:
            pass
    user_id = query.from_user.id
    for cache_dict in [ATTENDANCE_CACHE, GRADE_CACHE, HW_CACHE, REQ_CACHE, APP_CACHE, BEHAVIOR_CACHE, SUBMISSION_CACHE, EXAM_CACHE, BC_CACHE, PROP_CACHE]:
        cache_dict.pop(user_id, None)

    async with AsyncSessionLocal() as session:
        user = await session.get(User, user_id)
        lang = user.language if user else "tr"

    raw_data = str(query.data or "")
    target = raw_data.split(":", 1)[1] if ":" in raw_data else ""
    if target:
        # Avoid mutating query.data directly on frozen Pydantic model
        if target.startswith("prop:results:"):
            await cb_proposal_view_results(query)
