@router.callback_query(F.data.startswith("adm:do_unlink_st_tg:"))
async def cb_admin_do_unlink_st_tg(query: CallbackQuery):
    st_id = int(query.data.split(":")[2])
    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"
        if not is_admin_user(user, query.from_user.id):
            await query.answer(get_text("unauthorized_action", lang), show_alert=True)
            return

        st = await session.get(Student, st_id)
        if not st:
            await query.answer(get_text("student_not_found", lang), show_alert=True)
            return

        old_tg = st.student_telegram_id
        st.student_telegram_id = None
        st.is_student_code_burned = False
        st.student_code = generate_secure_code("OGR")

        if old_tg:
            old_u = await session.get(User, old_tg)
            if old_u and old_u.role == "student":
                old_u.role = "guest"
            try:
                msg_txt = {
                    "tr": "ℹ️ <b>BİLGİLENDİRME:</b> Okul idaresi tarafından Telegram hesabınızın öğrenci kaydı bağlantısı sıfırlanmıştır. Yeni şifrenizle tekrar giriş yapabilirsiniz.",
                    "ru": "ℹ️ <b>УВЕДОМЛЕНИЕ:</b> Администрация школы отвязала ваш Telegram от профиля ученика. Вы можете войти заново по новому коду.",
                    "uz": "ℹ️ <b>MA'LUMOT:</b> Maktab ma'muriyati Telegram hisobingizni o'quvchi profilidan uzdi. Yangi kod bilan qayta kirishingiz mumkin.",
                    "en": "ℹ️ <b>NOTICE:</b> Your Telegram account has been unlinked from student profile by school administration."
                }.get(old_u.language if old_u else "tr", "Telegram account unlinked.")
                await bot.send_message(chat_id=old_tg, text=msg_txt, parse_mode="HTML")
            except Exception: pass

        await log_audit(session, query.from_user.id, (user.full_name or "Yönetici"), "TELEGRAM KİLİDİ AÇILDI", f"Öğrenci Telegram bağı çözüldü: {st.full_name} ({st.class_name})")
        await session.commit()

        succ_txt = {
            "tr": "✅ Öğrencinin Telegram bağlantısı kesildi ve yeni giriş kodu oluşturuldu.",
            "ru": "✅ Telegram ученика успешно отвязан, создан новый код доступа.",
            "uz": "✅ O'quvchining Telegram hisobi uzildi va yangi kod yaratildi.",
            "en": "✅ Student Telegram unlinked and new code generated."
        }.get(lang, "Telegram unlinked.")
        await query.answer(succ_txt, show_alert=True)
    from aiogram.types import CallbackQuery
    dummy_q = CallbackQuery(id="0", from_user=query.from_user, chat_instance="0", message=query.message, data=f"adm:st_card:{st_id}")
    await cb_student_card(dummy_q)

# --- ÖĞRENCİ NOTLAR VE KARNE YÖNETİMİ ---
@router.callback_query(F.data.startswith("adm:st_grades:"))
async def cb_admin_student_grades(query: CallbackQuery):
    st_id = int(query.data.split(":")[2])
    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"
        if not is_admin_user(user, query.from_user.id):
            await query.answer(get_text("unauthorized_action", lang), show_alert=True)
            return

        st = await session.get(Student, st_id)
        if not st: return

        grades = (await session.execute(select(Grade).where(Grade.student_id == st.id).order_by(desc(Grade.created_at)))).scalars().all()

        hdr = {
            "tr": f"📊 <b>ÖĞRENCİ NOT VE KARNE YÖNETİMİ</b>\n────────────────────\n👤 <b>Öğrenci:</b> {escape_html(st.full_name)} (<code>{escape_html(st.class_name)}</code>)\n🔢 <b>Okul No:</b> <code>{escape_html(st.student_number)}</code>\n────────────────────",
            "ru": f"📊 <b>УПРАВЛЕНИЕ ОЦЕНКАМИ И ТАБЕЛЕМ</b>\n────────────────────\n👤 <b>Ученик:</b> {escape_html(st.full_name)} (<code>{escape_html(st.class_name)}</code>)\n🔢 <b>Номер:</b> <code>{escape_html(st.student_number)}</code>\n────────────────────",
            "uz": f"📊 <b>O'QUVCHINING BAHOLAR VA TABEL BOSHQARUVI</b>\n────────────────────\n👤 <b>O'quvchi:</b> {escape_html(st.full_name)} (<code>{escape_html(st.class_name)}</code>)\n🔢 <b>Raqami:</b> <code>{escape_html(st.student_number)}</code>\n────────────────────",
            "en": f"📊 <b>STUDENT GRADES & SCORECARD</b>\n────────────────────\n👤 <b>Student:</b> {escape_html(st.full_name)} (<code>{escape_html(st.class_name)}</code>)\n🔢 <b>Roll No:</b> <code>{escape_html(st.student_number)}</code>\n────────────────────"
        }.get(lang, "Student Grades:")

        buttons = []
        if not grades:
            no_gr_txt = {
                "tr": "ℹ️ <i>Bu öğrenciye ait henüz girilmiş sınav veya ders notu bulunmamaktadır.</i>",
                "ru": "ℹ️ <i>Для этого ученика еще нет внесенных оценок.</i>",
                "uz": "ℹ️ <i>Ushbu o'quvchiga hali baholar kiritilmagan.</i>",
                "en": "ℹ️ <i>No grades recorded for this student yet.</i>"
            }.get(lang, "No grades found.")
            body_txt = f"{hdr}\n{no_gr_txt}\n────────────────────"
        else:
            lines = []
            avg_score = sum(g.score for g in grades) / len(grades)
            for g in grades[:8]:
                lines.append(f"• <b>{escape_html(g.subject)}</b> ({escape_html(g.exam_type or 'Sınav')}): <code>{g.score}</code>")
                b_del_txt = {"tr": f"🗑️ {g.subject[:10]}: {g.score} Sil", "ru": f"🗑️ Удалить {g.score}", "uz": f"🗑️ O'chirish {g.score}", "en": f"🗑️ Delete {g.score}"}.get(lang, f"🗑️ Del {g.score}")
                buttons.append([InlineKeyboardButton(text=b_del_txt, callback_data=f"adm:del_gr:{g.id}:{st.id}")])

            body_txt = f"{hdr}\n📈 <b>Genel Ortalama:</b> <code>{avg_score:.1f}</code>\n\n" + "\n".join(lines) + "\n────────────────────"

        buttons.append([InlineKeyboardButton(text="➕ " + {"tr": "Yeni Not Ekle", "ru": "Добавить оценку", "uz": "Baho qo'shish", "en": "Add Grade"}.get(lang, "Add Grade"), callback_data=f"adm:add_gr_init:{st.id}")])
        buttons.append([InlineKeyboardButton(text=get_text("btn_back", lang), callback_data=f"adm:st_card:{st.id}")])

        await safe_edit_or_answer(query, body_txt, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons), parse_mode="HTML")
    await query.answer()

@router.callback_query(F.data.startswith("adm:del_gr:"))
async def cb_admin_del_grade(query: CallbackQuery):
    parts = query.data.split(":")
    gr_id = int(parts[2])
    st_id = int(parts[3])
    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"
        if not is_admin_user(user, query.from_user.id):
            await query.answer(get_text("unauthorized_action", lang), show_alert=True)
            return

        gr = await session.get(Grade, gr_id)
