@router.message(Form.adm_new_grade_subject)
async def process_admin_grade_subj(message: Message, state: FSMContext):
    try: await message.delete()
    except Exception: pass
    subj = message.text.strip()
    await state.update_data(add_gr_subj=subj)
    async with AsyncSessionLocal() as session:
        user = await session.get(User, message.from_user.id)
        lang = user.language if user else "tr"
        data = await state.get_data()
        st_id = data.get("add_gr_st_id")
        cancel_kb = get_inline_cancel_kb(lang, back_callback=f"adm:st_grades:{st_id}")
        prompt = {
            "tr": f"✍️ <b>{escape_html(subj)}</b> dersi için sınav notunu / puanını giriniz (0 - 100):",
            "ru": f"✍️ Введите балл по предмету <b>{escape_html(subj)}</b> (0 - 100):",
            "uz": f"✍️ <b>{escape_html(subj)}</b> fani uchun baho/ball kiriting (0 - 100):",
            "en": f"✍️ Enter score for <b>{escape_html(subj)}</b> (0 - 100):"
        }.get(lang, "Enter score:")
        await safe_edit_or_answer(message, prompt, reply_markup=cancel_kb, parse_mode="HTML")
        await state.set_state(Form.adm_new_grade_score)

@router.message(Form.adm_new_grade_score)
async def process_admin_grade_score(message: Message, state: FSMContext):
    try: await message.delete()
    except Exception: pass
    raw = message.text.strip().replace(",", ".")
    async with AsyncSessionLocal() as session:
        user = await session.get(User, message.from_user.id)
        lang = user.language if user else "tr"
        try:
            score = float(raw)
            if not (0 <= score <= 100): raise ValueError()
        except ValueError:
            await message.answer({"tr": "⚠️ Lütfen 0 ile 100 arasında geçerli bir puan giriniz!", "ru": "⚠️ Введите корректный балл от 0 до 100!", "uz": "⚠️ 0 dan 100 gacha to'g'ri ball kiriting!", "en": "⚠️ Enter a valid score between 0 and 100!"}.get(lang, "Invalid score."))
            return

        data = await state.get_data()
        st_id = data.get("add_gr_st_id")
        subj = data.get("add_gr_subj", "Genel")
        await state.clear()

        st = await session.get(Student, st_id)
        if not st: return

        badge = "🌟" if score >= 85 else ("👍" if score >= 70 else ("⚠️" if score >= 50 else "❌"))
        gr = Grade(
            student_id=st.id,
            subject=subj,
            exam_type="İdari Not Girişi",
            score=score,
            badge=badge,
            teacher_id=message.from_user.id
        )
        session.add(gr)
        await log_audit(session, message.from_user.id, (user.full_name or "Yönetici"), "NOT EKLENDİ", f"{st.full_name} - {subj}: {score}")
        await session.commit()

        from aiogram.types import CallbackQuery
        dummy_q = CallbackQuery(id="0", from_user=message.from_user, chat_instance="0", message=message, data=f"adm:st_grades:{st.id}")
        await cb_admin_student_grades(dummy_q)

# --- ÖĞRENCİ DEVAMSIZLIK & MAZERET YÖNETİMİ ---
@router.callback_query(F.data.startswith("adm:st_att:"))
async def cb_admin_student_attendance(query: CallbackQuery):
    st_id = int(query.data.split(":")[2])
    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"
        if not is_admin_user(user, query.from_user.id):
            await query.answer(get_text("unauthorized_action", lang), show_alert=True)
            return

        st = await session.get(Student, st_id)
        if not st: return

        all_att = (await session.execute(select(Attendance).where(Attendance.student_id == st.id).order_by(desc(Attendance.date)))).scalars().all()
        prs_cnt = sum(1 for a in all_att if a.status == "present")
        abs_cnt = sum(1 for a in all_att if a.status == "absent")
        med_cnt = sum(1 for a in all_att if a.status in ("medical", "excused"))

        hdr = {
            "tr": f"📋 <b>ÖĞRENCİ DEVAMSIZLIK & MAZERET YÖNETİMİ</b>\n────────────────────\n👤 <b>Öğrenci:</b> {escape_html(st.full_name)} (<code>{escape_html(st.class_name)}</code>)\n🔢 <b>Okul No:</b> <code>{escape_html(st.student_number)}</code>\n────────────────────\n• ✅ <b>Mevcut (Geldi):</b> {prs_cnt} gün\n• ❌ <b>Devamsız (Yok):</b> {abs_cnt} gün\n• 🏥 <b>Raporlu / İzinli:</b> {med_cnt} gün\n────────────────────",
            "ru": f"📋 <b>ПОСЕЩАЕМОСТЬ И СПРАВКИ УЧЕНИКА</b>\n────────────────────\n👤 <b>Ученик:</b> {escape_html(st.full_name)} (<code>{escape_html(st.class_name)}</code>)\n🔢 <b>Номер:</b> <code>{escape_html(st.student_number)}</code>\n────────────────────\n• ✅ <b>Присутствовал:</b> {prs_cnt} дн.\n• ❌ <b>Отсутствовал:</b> {abs_cnt} дн.\n• 🏥 <b>По справке / Уваж.:</b> {med_cnt} дн.\n────────────────────",
            "uz": f"📋 <b>DAVOMAT VA RUXSATNOMALAR BOSHQARUVI</b>\n────────────────────\n👤 <b>O'quvchi:</b> {escape_html(st.full_name)} (<code>{escape_html(st.class_name)}</code>)\n🔢 <b>Raqami:</b> <code>{escape_html(st.student_number)}</code>\n────────────────────\n• ✅ <b>Kelgan:</b> {prs_cnt} kun\n• ❌ <b>Kelmagan:</b> {abs_cnt} kun\n• 🏥 <b>Sababli / Ruxsatli:</b> {med_cnt} kun\n────────────────────",
            "en": f"📋 <b>ATTENDANCE & EXCUSE MANAGEMENT</b>\n────────────────────\n👤 <b>Student:</b> {escape_html(st.full_name)} (<code>{escape_html(st.class_name)}</code>)\n🔢 <b>Roll No:</b> <code>{escape_html(st.student_number)}</code>\n────────────────────\n• ✅ <b>Present:</b> {prs_cnt} days\n• ❌ <b>Absent:</b> {abs_cnt} days\n• 🏥 <b>Excused / Medical:</b> {med_cnt} days\n────────────────────"
        }.get(lang, "Attendance Summary:")

        buttons = []
        non_present = [a for a in all_att if a.status != "present"][:8]
        if non_present:
            for a in non_present:
                d_str = a.date.strftime("%d.%m")
                if a.status == "absent":
                    b_txt = {"tr": f"🏥 {d_str} Raporlu Yap", "ru": f"🏥 {d_str} По справке", "uz": f"🏥 {d_str} Sababli qilish", "en": f"🏥 {d_str} Excuse"}.get(lang, f"🏥 {d_str} Excuse")
                    buttons.append([InlineKeyboardButton(text=b_txt, callback_data=f"adm:tog_att_med:{a.id}:{st.id}")])
                else:
                    b_txt = {"tr": f"❌ {d_str} Devamsız Yap", "ru": f"❌ {d_str} Отсутствует", "uz": f"❌ {d_str} Kelmadi qilish", "en": f"❌ {d_str} Absent"}.get(lang, f"❌ {d_str} Absent")
                    buttons.append([InlineKeyboardButton(text=b_txt, callback_data=f"adm:tog_att_abs:{a.id}:{st.id}")])

        buttons.append([InlineKeyboardButton(text="➕ " + {"tr": "Bugüne İzin / Rapor Yaz", "ru": "Записать справку на сегодня", "uz": "Bugunga ruxsat yozish", "en": "Record Medical Leave Today"}.get(lang, "Add Leave"), callback_data=f"adm:add_leave_today:{st.id}")])
        buttons.append([InlineKeyboardButton(text=get_text("btn_back", lang), callback_data=f"adm:st_card:{st.id}")])

        await safe_edit_or_answer(query, hdr, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons), parse_mode="HTML")
    await query.answer()

