@router.callback_query(F.data.startswith("adm:add_leave_today:"))
async def cb_admin_add_leave_today(query: CallbackQuery):
    st_id = int(query.data.split(":")[2])
    async with AsyncSessionLocal() as session:
        st = await session.get(Student, st_id)
        if not st: return
        today = get_local_date()
        att = (await session.execute(select(Attendance).where(Attendance.student_id == st.id, Attendance.date == today))).scalar_one_or_none()
        if not att:
            att = Attendance(student_id=st.id, class_name=st.class_name, date=today, status="medical", teacher_id=query.from_user.id)
            session.add(att)
        else:
            att.status = "medical"
        await session.commit()
        await query.answer("🏥 Bugüne resmi mazeret/rapor kaydı işlendi.", show_alert=True)
    from aiogram.types import CallbackQuery
    dummy_q = CallbackQuery(id="0", from_user=query.from_user, chat_instance="0", message=query.message, data=f"adm:st_att:{st_id}")
    await cb_admin_student_attendance(dummy_q)

