@router.message(Form.adm_link_parent_val)
async def process_admin_link_parent(message: Message, state: FSMContext):
    try: await message.delete()
    except Exception: pass
    val = message.text.strip()
    data = await state.get_data()
    st_id = data.get("link_pr_st_id")
    await state.clear()

    async with AsyncSessionLocal() as session:
        admin_user = await session.get(User, message.from_user.id)
        lang = admin_user.language if admin_user else "tr"
        st = await session.get(Student, st_id)
        if not st: return

        target_parent = None
        if val.isdigit() and len(val) >= 6:
            target_parent = await session.get(User, int(val))
        if not target_parent:
            target_parent = (await session.execute(select(User).where(User.phone == val))).scalar_one_or_none()

        if not target_parent:
            err_txt = {
                "tr": f"⚠️ <code>{escape_html(val)}</code> bilgisine sahip kayıtlı kullanıcı bulunamadı! Velinin önce botu başlatmış (/start) olması gerekmektedir.",
                "ru": f"⚠️ Пользователь <code>{escape_html(val)}</code> не найден! Родитель должен предварительно запустить бота (/start).",
                "uz": f"⚠️ <code>{escape_html(val)}</code> ma'lumotiga ega foydalanuvchi topilmadi! Ota-ona avval botni boshlagan (/start) bo'lishi kerak.",
                "en": f"⚠️ User <code>{escape_html(val)}</code> not found! The parent must have started the bot (/start) first."
            }.get(lang, "Parent not found.")
            await message.answer(err_txt, parse_mode="HTML")
            return

        existing_link = (await session.execute(select(ParentStudent).where(ParentStudent.parent_telegram_id == target_parent.telegram_id, ParentStudent.student_id == st.id))).scalar_one_or_none()
        if existing_link:
            await message.answer({"tr": "⚠️ Bu veli zaten bu öğrenciye bağlı!", "ru": "⚠️ Этот родитель уже привязан к данному ученику!", "uz": "⚠️ Bu ota-ona ushbu o'quvchiga allaqachon biriktirilgan!", "en": "⚠️ This parent is already linked to this student!"}.get(lang, "Already linked."))
            return

        new_link = ParentStudent(parent_telegram_id=target_parent.telegram_id, student_id=st.id)
        session.add(new_link)
        if target_parent.role in ("guest", "student"):
            target_parent.role = "parent"
        st.is_parent_code_burned = True
        await log_audit(session, message.from_user.id, (admin_user.full_name or "Yönetici"), "VELİ BAĞLANDI", f"Veli: {target_parent.full_name} ({target_parent.telegram_id}) -> Öğrenci: {st.full_name}")
        await session.commit()

        try:
            p_msg = {
                "tr": f"🎓 <b>BİLGİLENDİRME:</b> Okul idaresi tarafından <b>{escape_html(st.full_name)}</b> ({escape_html(st.class_name)}) öğrencisi veli profilinize başarıyla bağlandı.",
                "ru": f"🎓 <b>УВЕДОМЛЕНИЕ:</b> Администрация школы привязала ученика <b>{escape_html(st.full_name)}</b> ({escape_html(st.class_name)}) к вашему профилю родителя.",
                "uz": f"🎓 <b>MA'LUMOT:</b> Maktab ma'muriyati tomonidan <b>{escape_html(st.full_name)}</b> ({escape_html(st.class_name)}) o'quvchisi profilingizga biriktirildi.",
                "en": f"🎓 <b>NOTICE:</b> Student <b>{escape_html(st.full_name)}</b> ({escape_html(st.class_name)}) has been linked to your parent profile by school administration."
            }.get(target_parent.language or "tr", "Student linked.")
            await bot.send_message(chat_id=target_parent.telegram_id, text=p_msg, parse_mode="HTML")
        except Exception: pass

        from aiogram.types import CallbackQuery
        dummy_q = CallbackQuery(id="0", from_user=message.from_user, chat_instance="0", message=message, data=f"adm:st_card:{st.id}")
        await cb_student_card(dummy_q)

