@router.message(Form.adm_edit_tch_subj)
async def process_admin_edit_t_subj(message: Message, state: FSMContext):
    try: await message.delete()
    except Exception: pass
    new_subj = message.text.strip()
    data = await state.get_data()
    tch_id = data.get("edit_tch_id")
    await state.clear()
    async with AsyncSessionLocal() as session:
        user = await session.get(User, message.from_user.id)
        lang = user.language if user else "tr"
        tch = await session.get(Teacher, tch_id)
        if tch:
            old_subj = tch.subject
            tch.subject = new_subj
            await log_audit(session, message.from_user.id, (user.full_name or "Yönetici"), "ÖĞRETMEN BRANŞI GÜNCELLENDİ", f"{tch.full_name}: {old_subj} -> {new_subj}")
            await session.commit()
            from aiogram.types import CallbackQuery
            dummy_q = CallbackQuery(id="0", from_user=message.from_user, chat_instance="0", message=message, data=f"adm:tch_card:{tch.id}")
            await cb_admin_teacher_card(dummy_q)

@router.callback_query(F.data.startswith("adm:tch_sched:"))
async def cb_admin_view_tch_sched(query: CallbackQuery):
    tch_id = int(query.data.split(":")[2])
    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"
        tch = await session.get(Teacher, tch_id)
        if not tch: return

        assigned_cls = [x.strip() for x in (tch.assigned_classes or "").split(",") if x.strip()]
        
        last_att = None
