        stat_body = {
            "tr": f"• <b>Son Alınan Yoklama:</b> {last_att_str}\n• <b>Sisteme Girilen Not Sayısı:</b> {recent_grades_cnt} adet",
            "ru": f"• <b>Последняя перекличка:</b> {last_att_str}\n• <b>Внесено оценок в базу:</b> {recent_grades_cnt} шт.",
            "uz": f"• <b>Oxirgi davomat:</b> {last_att_str}\n• <b>Kiritilgan baholar soni:</b> {recent_grades_cnt} ta",
            "en": f"• <b>Last Attendance:</b> {last_att_str}\n• <b>Total Grades Entered:</b> {recent_grades_cnt}"
        }.get(lang, "Activity:")

        full_txt = f"{lbl_hdr}\n{stat_body}\n────────────────────"
