@router.message(Form.add_student_name)
async def process_student_name(message: Message, state: FSMContext):
    async with AsyncSessionLocal() as session:
        user = await session.get(User, message.from_user.id)
        lang = user.language if user else "tr"

    name_val = message.text.strip() if message.text else ""
    if is_universal_cancel_text(name_val) or name_val.lower() in ("/cancel", "cancel", "iptal", "otmena", "bekor", "отмена"):
        await state.clear()
        try: await message.delete()
        except Exception: pass
        from aiogram.types import CallbackQuery
        dummy_q = CallbackQuery(id="0", from_user=message.from_user, chat_instance="0", message=message, data="adm:classes")
        await cb_classes_list(dummy_q, state)
        return
    if not name_val or len(name_val) < 1:
        await message.answer(get_text("student_name_invalid", lang))
        return
    await state.update_data(name=name_val)

    data = await state.get_data()
    cls_target = data.get("class_name")
    back_cb = f"adm:show_class:{cls_target}" if cls_target else "adm:classes"
    cancel_kb = get_inline_cancel_kb(lang, back_callback=back_cb)
    if cls_target:
        rec_num = int(await get_next_student_number(session))
        btn_q = {"tr": f"⚡ Otomatik Numara Ver ({rec_num})", "ru": f"⚡ Рекомендованный № ({rec_num})", "uz": f"⚡ Avtomatik raqam ({rec_num})", "en": f"⚡ Auto Number ({rec_num})"}.get(lang, f"⚡ Auto Number ({rec_num})")
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text=btn_q, callback_data=f"adm:add_st_quick_no:{rec_num}")],
            [InlineKeyboardButton(text=get_text("btn_cancel_action", lang), callback_data=back_cb)]
        ])
        await safe_edit_or_answer(message, get_text("prompt_student_no", lang) + f" (Öneri: <code>{rec_num}</code>):", reply_markup=kb, parse_mode="HTML")
        await state.set_state(Form.add_student_no)
        return

    classes = await get_all_school_classes(session)
    cls_buttons = []
    row = []
    for c in classes:
        row.append(InlineKeyboardButton(text=f"🏫 {c}", callback_data=f"adm:add_st_cls:{c}"))
        if len(row) == 3:
            cls_buttons.append(row)
            row = []
    if row: cls_buttons.append(row)
    cls_buttons.append([InlineKeyboardButton(text=get_text("btn_cancel_action", lang), callback_data="adm:classes")])
    await safe_edit_or_answer(message, get_text("prompt_student_class", lang), reply_markup=InlineKeyboardMarkup(inline_keyboard=cls_buttons), parse_mode="HTML")
    await state.set_state(Form.add_student_class)

