@router.callback_query(F.data.startswith("adm:teachers"))
async def cb_admin_teachers_list(query: CallbackQuery, state: FSMContext | None = None):
    try: await query.answer()
    except Exception: pass
    if state: await state.clear()
    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"

        parts = query.data.split(":")
        page = int(parts[2]) if len(parts) > 2 and parts[2].isdigit() else 0
        PAGE_SIZE = 10

        teachers = (await session.execute(select(Teacher).order_by(Teacher.full_name))).scalars().all()
        total_teachers = len(teachers)
        total_pages = max(1, (total_teachers + PAGE_SIZE - 1) // PAGE_SIZE)
        page = max(0, min(page, total_pages - 1))
        paged_teachers = teachers[page * PAGE_SIZE : (page + 1) * PAGE_SIZE]

        buttons = []
        for t in paged_teachers:
            status_dot = "🟢" if t.telegram_id else "⚪"
            t_name = t.full_name or "Öğretmen"
            if len(t_name) > 11:
                t_name = t_name[:10] + "…"
            if re.search(r'[؀-ۿ]', t_name):
                t_name = f"{t_name}‎"
            t_sub = t.subject or ""
            if len(t_sub) > 7:
                t_sub = t_sub[:6] + "…"
            btn_txt = f"{status_dot} {t_name}" + (f" • {t_sub}" if t_sub else "")
            buttons.append([InlineKeyboardButton(text=btn_txt, callback_data=f"adm:tch_card:{t.id}")])

        if total_pages > 1:
            nav_row = []
            if page > 0:
                nav_row.append(InlineKeyboardButton(text=get_text("btn_prev", lang), callback_data=f"adm:teachers:{page-1}"))
            nav_row.append(InlineKeyboardButton(text=f"📄 {page+1}/{total_pages}", callback_data="noop"))
            if page < total_pages - 1:
                nav_row.append(InlineKeyboardButton(text=get_text("btn_next", lang), callback_data=f"adm:teachers:{page+1}"))
            buttons.append(nav_row)

        buttons.append([
            InlineKeyboardButton(text=get_text("btn_search_teacher", lang), callback_data="adm:search_teacher"),
            InlineKeyboardButton(text=get_text("btn_add_new_teacher", lang), callback_data="adm:add_teacher")
        ])
        buttons.append(get_nav_buttons(lang, back_callback="adm:cat_staff"))

        teachers_list_title = {
            "tr": f"👨‍🏫 <b>ÖĞRETMEN KADROSU</b> ({page+1}/{total_pages})\n────────────────────\n• Toplam: <b>{total_teachers}</b> öğretmen\n────────────────────\n<i>Detay veya yetki işlemleri için seçiniz:</i>",
            "ru": f"👨‍🏫 <b>СПИСОК УЧИТЕЛЕЙ</b> ({page+1}/{total_pages})\n────────────────────\n• Всего: <b>{total_teachers}</b> учителей\n────────────────────\n<i>Выберите для просмотра профиля или прав:</i>",
            "uz": f"👨‍🏫 <b>O'QITUVCHILAR RO'YXATI</b> ({page+1}/{total_pages})\n────────────────────\n• Jami: <b>{total_teachers}</b> ta o'qituvchi\n────────────────────\n<i>Tafsilotlar yoki vakolatlar uchun tanlang:</i>",
            "en": f"👨‍🏫 <b>TEACHERS DIRECTORY</b> ({page+1}/{total_pages})\n────────────────────\n• Total: <b>{total_teachers}</b> teachers\n────────────────────\n<i>Tap to manage profile or permissions:</i>"
        }.get(lang, f"👨‍🏫 <b>TEACHERS DIRECTORY</b> ({page+1}/{total_pages})\n────────────────────\n• Total: <b>{total_teachers}</b>\n────────────────────")
        await safe_edit_or_answer(query, teachers_list_title, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons), parse_mode="HTML")

