@router.callback_query(F.data.startswith("adm:show_class:"))
async def cb_show_class_students(query: CallbackQuery):
    try: await query.answer()
    except Exception: pass
    parts = query.data.split(":")
    class_name = parts[2]
    page = int(parts[3]) if len(parts) > 3 and parts[3].isdigit() else 0
    PAGE_SIZE = 10

    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"

        all_students = (await session.execute(select(Student).where(Student.class_name == class_name).order_by(Student.student_number))).scalars().all()
        total_students = len(all_students)
        total_pages = max(1, (total_students + PAGE_SIZE - 1) // PAGE_SIZE)
        page = max(0, min(page, total_pages - 1))

        all_teachers = (await session.execute(select(Teacher))).scalars().all()
        class_teachers = [t for t in all_teachers if t.assigned_classes == "ALL" or class_name in [x.strip() for x in (t.assigned_classes or "").split(",")]]
        tch_names = [f"{t.full_name} ({t.subject})" for t in class_teachers]
        val_not_assigned = {"tr": "Henüz Atanmadı", "ru": "Еще не назначен", "uz": "Hali biriktirilmagan", "en": "Not Assigned Yet"}.get(lang, "Not Assigned Yet")
        tch_summary = ", ".join(tch_names) if tch_names else val_not_assigned

        tch_short = tch_summary
        if len(tch_short) > 35:
            tch_short = tch_short[:33] + "…"

        hdr_class_box = {
            "tr": f"🏫 <b>SINIF LİSTESİ: {escape_html(class_name)}</b> ({page + 1}/{total_pages})\n────────────────────\n• Toplam: <b>{total_students}</b> öğrenci\n• Öğretmenler: <i>{escape_html(tch_short)}</i>\n────────────────────",
            "ru": f"🏫 <b>СПИСОК КЛАССА {escape_html(class_name)}</b> ({page + 1}/{total_pages})\n────────────────────\n• Всего: <b>{total_students}</b> уч.\n• Учителя: <i>{escape_html(tch_short)}</i>\n────────────────────",
            "uz": f"🏫 <b>{escape_html(class_name)} SINFI RO'YXATI</b> ({page + 1}/{total_pages})\n────────────────────\n• Jami: <b>{total_students}</b> o'quvchi\n• O'qituvchilar: <i>{escape_html(tch_short)}</i>\n────────────────────",
            "en": f"🏫 <b>CLASS ROSTER: {escape_html(class_name)}</b> ({page + 1}/{total_pages})\n────────────────────\n• Total: <b>{total_students}</b> students\n• Teachers: <i>{escape_html(tch_short)}</i>\n────────────────────"
        }.get(lang, f"🏫 <b>CLASS: {escape_html(class_name)}</b>\n────────────────────\n• Total: <b>{total_students}</b>\n────────────────────")

        btn_add_to_cls = {"tr": "➕ Bu Sınıfa Öğrenci Ekle", "ru": "➕ Добавить ученика", "uz": "➕ O'quvchi qo'shish", "en": "➕ Add Student"}.get(lang, "➕ Add Student")
        btn_del_cls = {"tr": "🗑️ Sınıfı Sil", "ru": "🗑️ Удалить класс", "uz": "🗑️ Sinfni o'chirish", "en": "🗑️ Delete Class"}.get(lang, "🗑️ Delete Class")

        buttons = []

        if total_students == 0:
            empty_hint = {
                "tr": "ℹ️ <i>Bu sınıfta henüz kayıtlı öğrenci bulunmamaktadır.</i>",
                "ru": "ℹ️ <i>В этом классе пока нет зарегистрированных учеников.</i>",
                "uz": "ℹ️ <i>Ushbu sinfda hali o'quvchilar ro'yxatga olinmagan.</i>",
                "en": "ℹ️ <i>No students are currently registered in this class.</i>"
            }.get(lang, "No students registered.")
            buttons = [
                [InlineKeyboardButton(text=btn_add_to_cls, callback_data=f"adm:add_st_to_cls:{class_name}")],
                [InlineKeyboardButton(text=btn_del_cls, callback_data=f"adm:del_class_prompt:{class_name}")],
                get_nav_buttons(lang, back_callback="adm:classes")
            ]
            class_list_title = f"{hdr_class_box}\n{empty_hint}"
        else:
            start_idx = page * PAGE_SIZE
            paged_students = all_students[start_idx : start_idx + PAGE_SIZE]

            for s in paged_students:
                clean_name = s.full_name or "Öğrenci"
                if len(clean_name) > 11:
                    clean_name = clean_name[:10] + "…"
                if re.search(r'[\u0600-\u06FF]', clean_name):
                    clean_name = f"{clean_name}\u200e"
                st_no = s.student_number or ""
                btn_txt = f"🎓 {clean_name} • №{st_no}\u200e"
                buttons.append([InlineKeyboardButton(text=btn_txt, callback_data=f"adm:st_card:{s.id}:{page}")])

            if total_pages > 1:
                nav_row = []
                if page > 0:
                    nav_row.append(InlineKeyboardButton(text=get_text("btn_prev", lang), callback_data=f"adm:show_class:{class_name}:{page - 1}"))
                nav_row.append(InlineKeyboardButton(text=f"📄 {page + 1}/{total_pages}", callback_data="noop"))
                if page < total_pages - 1:
                    nav_row.append(InlineKeyboardButton(text=get_text("btn_next", lang), callback_data=f"adm:show_class:{class_name}:{page + 1}"))
                buttons.append(nav_row)

            buttons.append([InlineKeyboardButton(text=btn_add_to_cls, callback_data=f"adm:add_st_to_cls:{class_name}")])
