@router.callback_query(F.data.startswith("adm:st_card:"))
async def cb_student_card(query: CallbackQuery):
    parts = query.data.split(":")
    st_id = int(parts[2])
    page = int(parts[3]) if len(parts) > 3 and parts[3].isdigit() else 0
    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"
        st = await session.get(Student, st_id)
        if not st:
            await query.answer(get_text("student_not_found", lang), show_alert=True)
            return

        lbl_used = {"tr": "Kullanıldı", "ru": "Использован", "uz": "Ishlatildi", "en": "Used"}.get(lang, "Used")
        lbl_free = {"tr": "Aktif / Boşta", "ru": "Активен / Свободен", "uz": "Faol / Bo'sh", "en": "Active / Unused"}.get(lang, "Active")
        st_status = lbl_used if st.is_student_code_burned else lbl_free
        pr_status = lbl_used if st.is_parent_code_burned else lbl_free

        parents = (await session.execute(select(User).join(ParentStudent, ParentStudent.parent_telegram_id == User.telegram_id).where(ParentStudent.student_id == st.id))).scalars().all()
        p_label_def = {"tr": "Veli", "ru": "Родитель", "uz": "Ota-ona", "en": "Parent"}.get(lang, "Parent")
        no_parent_txt = {"tr": "Henüz bağlı veli yok", "ru": "Нет привязанных родителей", "uz": "Biriktirilgan ota-ona yo'q", "en": "No linked parents"}.get(lang, "None")
        if parents:
            parent_lines = [f"• {escape_html(p.full_name or p_label_def)} (<code>{p.telegram_id}</code>)" for p in parents]
            p_info = "\n" + "\n".join(parent_lines)
        else:
            p_info = f" <i>{no_parent_txt}</i>"

        t_card_title = {"tr": "🧑‍🎓 <b>ÖĞRENCİ BİLGİ KARTI</b>", "ru": "🧑‍🎓 <b>КАРТОЧКА УЧЕНИКА</b>", "uz": "🧑‍🎓 <b>O'QUVCHI KARTASI</b>", "en": "🧑‍🎓 <b>STUDENT CARD</b>"}.get(lang, "🧑‍🎓 <b>STUDENT CARD</b>")
        lbl_cls_w = {"tr": "Sınıf", "ru": "Класс", "uz": "Sinf", "en": "Class"}.get(lang, "Class")
        lbl_no_w = {"tr": "Okul No", "ru": "Номер в школе", "uz": "Maktab raqami", "en": "Roll No"}.get(lang, "No")
        lbl_st_code = {"tr": "Öğrenci Kodu", "ru": "Код ученика", "uz": "O'quvchi kodi", "en": "Student Code"}.get(lang, "Student Code")
        lbl_pr_code = {"tr": "Veli Kodu", "ru": "Код родителя", "uz": "Ota-ona kodi", "en": "Parent Code"}.get(lang, "Parent Code")
        lbl_pr_w = {"tr": "Bağlı Veli", "ru": "Родители", "uz": "Bog'langan ota-ona", "en": "Linked Parents"}.get(lang, "Parents")

        text = (
            f"{t_card_title}\n"
            "────────────────────\n"
            f"👤 <b>{escape_html(st.full_name)}</b>\n"
            f"🏫 <b>{lbl_cls_w}:</b> {escape_html(st.class_name)} │ <b>{lbl_no_w}:</b> <code>{escape_html(st.student_number)}</code>\n"
            "────────────────────\n"
            f"🔑 <b>{lbl_st_code}:</b> <code>{st.student_code}</code> ({st_status})\n"
            f"🔐 <b>{lbl_pr_code}:</b> <code>{st.parent_code}</code> ({pr_status})\n"
            f"👨‍👩‍👧‍👦 <b>{lbl_pr_w}:</b>{p_info}\n"
            "────────────────────"
        )

        buttons = [
            [
                InlineKeyboardButton(text=get_text("btn_edit_student", lang), callback_data=f"adm:edit_st:{st.id}"),
                InlineKeyboardButton(text=get_text("btn_st_grades", lang), callback_data=f"adm:st_grades:{st.id}")
            ],
            [
                InlineKeyboardButton(text=get_text("btn_st_att_excuse", lang), callback_data=f"adm:st_att:{st.id}"),
                InlineKeyboardButton(text=get_text("btn_behavior", lang), callback_data=f"bh_st:{st.id}")
            ],
            [
                InlineKeyboardButton(text=get_text("btn_link_parent", lang), callback_data=f"adm:link_pr_init:{st.id}")
            ]
        ]
        if parents:
            buttons[-1].append(InlineKeyboardButton(text=get_text("btn_unlink_parent", lang), callback_data=f"adm:unlink_pr:{st.id}"))
        
        row_sec = [InlineKeyboardButton(text=get_text("btn_reset_codes", lang), callback_data=f"adm:prompt_reset_st:{st.id}")]
        if st.student_telegram_id:
            row_sec.append(InlineKeyboardButton(text=get_text("btn_unlink_telegram", lang), callback_data=f"adm:unlink_st_tg:{st.id}"))
        buttons.append(row_sec)

        buttons.append([InlineKeyboardButton(text=get_text("btn_del_student", lang), callback_data=f"adm:del_student:{st.id}")])
        buttons.append(get_nav_buttons(lang, back_callback=f"adm:show_class:{st.class_name}:{page}"))
        await safe_edit_or_answer(query, text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons), parse_mode="HTML")
    await query.answer()

