        lbl_change_role = {"tr": "🎭 Rol Yönetimi & Ata", "ru": "🎭 Сменить роль", "uz": "🎭 Rolni boshqarish", "en": "🎭 Manage / Assign Role"}.get(lang, "🎭 Manage Role")
