@router.callback_query(F.data.startswith("adm:set_role:"))
async def cb_admin_set_role(query: CallbackQuery):
    parts = query.data.split(":")
    tg_id = int(parts[2])
    new_role = parts[3]
    page = int(parts[4]) if len(parts) > 4 and parts[4].isdigit() else 0

    async with AsyncSessionLocal() as session:
        admin_u = await session.get(User, query.from_user.id)
        lang = admin_u.language if admin_u else "tr"
        if not is_admin_user(admin_u, query.from_user.id):
            await query.answer()
            return

        target_u = await session.get(User, tg_id)
        if not target_u:
            await query.answer(get_text("user_not_found_toast", lang), show_alert=True)
            return

        target_u.role = new_role
        if new_role != "admin" and tg_id not in PERMANENT_ADMIN_IDS:
            target_u.admin_type = "none"
            target_u.admin_until = None
        await session.commit()

        t_lang = target_u.language or "tr"
        role_label_t = {
            "tr": {"teacher": "Öğretmen", "student": "Öğrenci", "parent": "Veli", "guest": "Misafir"},
            "ru": {"teacher": "Учитель", "student": "Ученик", "parent": "Родитель", "guest": "Гость"},
            "uz": {"teacher": "O'qituvchi", "student": "O'quvchi", "parent": "Ota-ona", "guest": "Mehmon"},
            "en": {"teacher": "Teacher", "student": "Student", "parent": "Parent", "guest": "Guest"}
        }.get(t_lang, {}).get(new_role, new_role)

        notify_text = {
            "tr": f"🔔 <b>Sistem Rolünüz Güncellendi</b>\n────────────────────\nYeni rolünüz: <b>{role_label_t}</b> olarak ayarlandı.\nAna menüye dönmek için /start yazabilirsiniz.",
            "ru": f"🔔 <b>Ваша роль в системе обновлена</b>\n────────────────────\nНовая роль: <b>{role_label_t}</b>.\nВведите /start для обновления главного меню.",
            "uz": f"🔔 <b>Tizimdagi rolingiz yangilandi</b>\n────────────────────\nYangi rolingiz: <b>{role_label_t}</b>.\nAsosiy menyuni yangilash uchun /start buyrug'ini yuboring.",
            "en": f"🔔 <b>Your System Role Was Updated</b>\n────────────────────\nYour new role is: <b>{role_label_t}</b>.\nSend /start to refresh your main menu."
        }.get(t_lang, f"Your role is now: {role_label_t}")

        try:
            bot_instance = query.bot if getattr(query, 'bot', None) else (query.message.bot if query.message else bot)
            await bot_instance.send_message(chat_id=tg_id, text=notify_text, parse_mode="HTML")
        except Exception:
            pass

        success_toast = {
            "tr": f"✅ Rol başarıyla '{role_label_t}' olarak güncellendi!",
            "ru": f"✅ Роль успешно изменена на '{role_label_t}'!",
            "uz": f"✅ Rol muvaffaqiyatli '{role_label_t}' qilib o'zgartirildi!",
            "en": f"✅ Role successfully updated to '{role_label_t}'!"
        }.get(lang, "✅ Role updated!")

        await query.answer(success_toast, show_alert=True)

    dummy_q = CallbackQuery(id="0", from_user=query.from_user, chat_instance=getattr(query, 'chat_instance', '0'), message=query.message, data=f"adm:user_card:{tg_id}:{page}")
    await cb_admin_user_card(dummy_q)

@router.callback_query(F.data.startswith("adm:user_360:"))
async def cb_admin_user_360(query: CallbackQuery):
    parts = query.data.split(":")
    tg_id = int(parts[2])
    page = int(parts[3]) if len(parts) > 3 and parts[3].isdigit() else 0
    is_ref = len(parts) > 4 and parts[4] == "ref"

    async with AsyncSessionLocal() as session:
        admin_u = await session.get(User, query.from_user.id)
        lang = admin_u.language if admin_u else "tr"
        if not is_admin_user(admin_u, query.from_user.id):
            await query.answer(get_text("unauthorized_action", lang), show_alert=True)
            return

        target_u = await session.get(User, tg_id)
        if not target_u:
            await query.answer(get_text("user_not_found_toast", lang), show_alert=True)
            return

        now = datetime.utcnow()
        now_clock = (now + timedelta(hours=TIMEZONE_OFFSET)).strftime("%H:%M")

        # Eğer yönetici kendi profiline bakıyorsa veya yenileye bastıysa canlı aktifliğini doğrudan mühürle
        if tg_id == query.from_user.id:
            target_u.last_seen_at = now
            cur_act = {
                "tr": f"360° İstihbarat Paneli İncelendi ({now_clock})",
                "ru": f"Просмотр 360° досье ({now_clock})",
                "uz": f"360° dosye ko'rildi ({now_clock})",
                "en": f"Viewed 360° Dossier ({now_clock})"
            }.get(lang, "Viewed 360° Dossier")
            target_u.last_action_desc = cur_act
            await session.commit()

        raw_name = target_u.full_name or ""
        clean_name = re.sub(r'[\.\s\-_]+', '', str(raw_name or ''))
        unkn_txt = {"tr": "Bilinmeyen", "ru": "Неизвестно", "uz": "Noma'lum", "en": "Unknown"}.get(lang, "Unknown")
        display_name = raw_name if clean_name else (get_text("permanent_admin_title", lang) if (tg_id in PERMANENT_ADMIN_IDS or target_u.admin_type == "permanent") else unkn_txt)
        usr_display_tag = f"(@{target_u.username})" if target_u.username else ""

        role_labels_all = {
            "admin": {"tr": "Yönetici", "ru": "Администратор", "uz": "Administrator", "en": "Administrator"},
            "teacher": {"tr": "Öğretmen", "ru": "Учитель", "uz": "O'qituvchi", "en": "Teacher"},
            "parent": {"tr": "Veli", "ru": "Родитель", "uz": "Ota-ona", "en": "Parent"},
            "student": {"tr": "Öğrenci", "ru": "Ученик", "uz": "O'quvchi", "en": "Student"},
            "guest": {"tr": "Misafir", "ru": "Гость", "uz": "Mehmon", "en": "Guest"}
        }
        role_label = role_labels_all.get(target_u.role, {}).get(lang, target_u.role)
        lbl_role_prefix = {"tr": "Rol", "ru": "Роль", "uz": "Roli", "en": "Role"}.get(lang, "Role")

        # 1. Canlı Durum & Son Görülme (Sıfır Hata & Anlık Gösterge)
        live_badge = "🟢"
        if target_u.is_bot_blocked:
            live_badge = "🔴"
            live_status = {"tr": "Botu Engelledi / Çıktı", "ru": "Заблокировал бота / Вышел", "uz": "Botni blokladi / Chiqib ketdi", "en": "Blocked Bot / Left"}.get(lang, "Blocked Bot")
        elif target_u.last_seen_at:
            diff_secs = max(0, (now - target_u.last_seen_at).total_seconds())
            if diff_secs < 90:
                live_status = {"tr": "Çevrimiçi (Az önce)", "ru": "В сети (Только что)", "uz": "Onlayn (Hozirgina)", "en": "Online (Just now)"}.get(lang, "Online (Just now)")
            elif diff_secs < 3600:
                m = max(1, int(diff_secs // 60))
                live_status = {"tr": f"Çevrimiçi ({m} dk önce)", "ru": f"В сети ({m} мин. назад)", "uz": f"Onlayn ({m} daq. oldin)", "en": f"Online ({m} min ago)"}.get(lang, f"Online ({m} min ago)")
            elif diff_secs < 86400:
                h = max(1, int(diff_secs // 3600))
                live_badge = "🟡"
                live_status = {"tr": f"Bugün Aktif ({h} sa önce)", "ru": f"Активен сегодня ({h} ч. назад)", "uz": f"Bugun faol ({h} soat oldin)", "en": f"Active today ({h} hr ago)"}.get(lang, f"Active today ({h} hr ago)")
            else:
                d = max(1, int(diff_secs // 86400))
                live_badge = "🔴"
                live_status = {"tr": f"Pasif ({d} gündür girmedi)", "ru": f"Неактивен ({d} дн. без входа)", "uz": f"Nofaol ({d} kundan beri kirmadi)", "en": f"Inactive ({d} days absent)"}.get(lang, f"Inactive ({d} days)")
        else:
            live_badge = "⚪"
            live_status = {"tr": "Henüz etkileşim yok", "ru": "Нет активности", "uz": "Hali faollik yo'q", "en": "No activity yet"}.get(lang, "No activity yet")

        # 2. İtaat & Tepki Hızı (Latency)
        acks = (await session.execute(
            select(BroadcastAck, BroadcastNotice)
            .join(BroadcastNotice, BroadcastAck.notice_id == BroadcastNotice.id)
            .where(BroadcastAck.user_telegram_id == tg_id)
            .order_by(desc(BroadcastAck.acknowledged_at))
            .limit(5)
        )).tuples().all()

        lats = []
        if acks:
            for row in acks:
                try:
                    ack, notice = row[0], row[1]
                    if getattr(ack, 'acknowledged_at', None) and getattr(notice, 'created_at', None):
                        lats.append((ack.acknowledged_at - notice.created_at).total_seconds() / 60)
                except Exception: pass

        if lats:
            avg_m = round(sum(lats) / len(lats), 1)
            if avg_m <= 5:
                itaat_txt = {"tr": f"~{avg_m} dk (A Sınıfı - Anında)", "ru": f"~{avg_m} мин (Класс A - Мгновенно)", "uz": f"~{avg_m} daq (A Sinf - Tezkor)", "en": f"~{avg_m} min (Class A - Instant)"}.get(lang, f"~{avg_m} min")
            elif avg_m <= 30:
                itaat_txt = {"tr": f"~{avg_m} dk (B Sınıfı - Standart)", "ru": f"~{avg_m} мин (Класс B - Стандарт)", "uz": f"~{avg_m} daq (B Sinf - Standart)", "en": f"~{avg_m} min (Class B - Standard)"}.get(lang, f"~{avg_m} min")
            else:
                itaat_txt = {"tr": f"~{avg_m} dk (C Sınıfı - Gecikmeli)", "ru": f"~{avg_m} мин (Класс C - С задержкой)", "uz": f"~{avg_m} daq (C Sinf - Kechikkan)", "en": f"~{avg_m} min (Class C - Delayed)"}.get(lang, f"~{avg_m} min")
        else:
            itaat_txt = {"tr": "Onay kaydı yok", "ru": "Нет записей подтверждений", "uz": "Tasdiq yozuvi yo'q", "en": "No records"}.get(lang, "No records")

        # 3. Güvenlik & Tehdit Skoru (0 - 100)
        score = 100
        if target_u.is_blacklisted:
            score = 0
        else:
            score -= (target_u.failed_attempts or 0) * 15
            score -= (target_u.night_activity_count or 0) * 10
            if target_u.is_bot_blocked: score -= 25
            score = max(0, min(100, score))

        if score >= 85:
            score_badge = "🛡️"
            score_txt = {"tr": f"%{score} (A Sınıfı)", "ru": f"{score}% (Класс A)", "uz": f"{score}% (A Sinf)", "en": f"{score}% (Class A)"}.get(lang, f"{score}%")
        elif score >= 60:
            score_badge = "🟡"
            score_txt = {"tr": f"%{score} (B Sınıfı)", "ru": f"{score}% (Класс B)", "uz": f"{score}% (B Sinf)", "en": f"{score}% (Class B)"}.get(lang, f"{score}%")
        elif score >= 40:
            score_badge = "🟠"
            score_txt = {"tr": f"%{score} (C Sınıfı)", "ru": f"{score}% (Класс C)", "uz": f"{score}% (C Sinf)", "en": f"{score}% (Class C)"}.get(lang, f"{score}%")
        else:
            score_badge = "🔴"
            score_txt = {"tr": f"%{score} (D Sınıfı - Risk)", "ru": f"{score}% (Класс D - Риск)", "uz": f"{score}% (D Sinf - Xavf)", "en": f"{score}% (Class D - Risk)"}.get(lang, f"{score}%")

        # 4. Biyolojik Saat / Zaman Anomalisi
        night_cnt = target_u.night_activity_count or 0
        if night_cnt > 0:
            rutin_txt = {"tr": f"⚠️ Gece {night_cnt} işlem (01:00-06:00)", "ru": f"⚠️ Ночь: {night_cnt} действ. (01:00-06:00)", "uz": f"⚠️ Tun: {night_cnt} ta amal (01:00-06:00)", "en": f"⚠️ Night: {night_cnt} actions (01:00-06:00)"}.get(lang, f"⚠️ Night: {night_cnt}")
        else:
            rutin_txt = {"tr": "Düzgün Gündüz Rutini", "ru": "Дневной режим (Норма)", "uz": "Kunduzgi tartib (Me'yor)", "en": "Normal Daytime Routine"}.get(lang, "Normal Daytime")

        # 5. Kimlik Değişim Geçmişi
        names_log = []
        try: names_log = json.loads(target_u.previous_names) if target_u.previous_names else []
        except Exception: pass
        if names_log:
            last_n = names_log[-1]
            c_cnt = len(names_log)
            old_v = last_n.get('old', '')
            new_v = last_n.get('new', '')
            alias_txt = {"tr": f"{c_cnt} Değişiklik ({old_v} ➔ {new_v})", "ru": f"{c_cnt} изм. ({old_v} ➔ {new_v})", "uz": f"{c_cnt} ta o'zgarish ({old_v} ➔ {new_v})", "en": f"{c_cnt} change(s) ({old_v} ➔ {new_v})"}.get(lang, f"{c_cnt} changes")
        else:
            alias_txt = {"tr": "Sabit (Değişiklik yok)", "ru": "Стабильно (Без изменений)", "uz": "O'zgarmas (O'zgarishsiz)", "en": "Constant (No changes)"}.get(lang, "Constant")

        # 6. Tipoloji / İlgi Alanı
        p_map = {}
        try: p_map = json.loads(target_u.persona_counts) if target_u.persona_counts else {}
        except Exception: pass
        top_act = max(p_map, key=p_map.get) if p_map else "standart"
        if top_act in ("grade", "exam"):
            persona_txt = {"tr": "🎯 Başarı & Not Odaklı", "ru": "🎯 Оценки и успеваемость", "uz": "🎯 Baholar va natijalar", "en": "🎯 Academic & Grades"}.get(lang, "Academic")
        elif top_act in ("attendance", "excuse"):
            persona_txt = {"tr": "⚠️ Devamsızlık & İzin", "ru": "⚠️ Пропуски и справки", "uz": "⚠️ Davomat va ruxsatlar", "en": "⚠️ Attendance & Excuses"}.get(lang, "Attendance")
        elif top_act == "menu":
            persona_txt = {"tr": "🍲 Yemek & Menü", "ru": "🍲 Меню столовой", "uz": "🍲 Oshxona menyusi", "en": "🍲 Cafeteria Menu"}.get(lang, "Cafeteria")
        elif top_act == "download":
            persona_txt = {"tr": "📑 Evrak & Dosyalar", "ru": "📑 Документы и выгрузки", "uz": "📑 Hujjatlar va fayllar", "en": "📑 Documents & Files"}.get(lang, "Documents")
        else:
            persona_txt = {"tr": "💤 Standart / Seyrek", "ru": "💤 Редкий контакт / Норма", "uz": "💤 Kam muloqot / Me'yor", "en": "💤 Minimal Contact / Normal"}.get(lang, "Normal")

        # 7. Veri Hacmi
        dl_cnt = target_u.download_count or 0
        if dl_cnt >= 10:
            dl_txt = {"tr": f"🚨 Yüksek Hacim ({dl_cnt} dosya)", "ru": f"🚨 Высокий объем ({dl_cnt} файлов)", "uz": f"🚨 Yuqori hajm ({dl_cnt} ta fayl)", "en": f"🚨 High Volume ({dl_cnt} files)"}.get(lang, f"🚨 {dl_cnt} files")
        else:
            dl_txt = {"tr": f"Normal ({dl_cnt} indirme)", "ru": f"Нормально ({dl_cnt} скачиваний)", "uz": f"Oddiy ({dl_cnt} ta yuklash)", "en": f"Normal ({dl_cnt} downloads)"}.get(lang, f"Normal ({dl_cnt})")

        excuse_360_txt = ""
        st_360 = (await session.execute(select(Student).where(Student.student_telegram_id == tg_id))).scalar_one_or_none()
        if st_360:
            st_ex = (await session.execute(select(Attendance).where(Attendance.student_id == st_360.id, Attendance.status == "excused"))).scalars().all()
            if len(st_ex) >= 3:
                mf_cnt = sum(1 for a in st_ex if getattr(a, 'date', None) and hasattr(a.date, 'weekday') and a.date.weekday() in (0, 4))
                if mf_cnt / len(st_ex) >= 0.6:
                    pct = int(round(mf_cnt * 100 / len(st_ex)))
                    excuse_lbl = {
                        "tr": f"\n⚠️ <b>İzin Eğilimi:</b> %{pct} Cuma/Pzt (Hafta sonu uzatma)",
                        "ru": f"\n⚠️ <b>Паттерн пропусков:</b> {pct}% Пт/Пн (Продление выходных)",
                        "uz": f"\n⚠️ <b>Ruxsat moyilligi:</b> {pct}% Juma/Dush (Dam olishni cho'zish)",
                        "en": f"\n⚠️ <b>Absence Pattern:</b> {pct}% Fri/Mon (Weekend extension)"
                    }.get(lang, f"\n⚠️ <b>Pattern:</b> {pct}% Fri/Mon")
                    excuse_360_txt = excuse_lbl

        # 8. Son Hareket
        if target_u.last_action_desc:
            last_act = target_u.last_action_desc
        else:
            last_act = {"tr": "Kayıtlı son işlem yok", "ru": "Нет записей действий", "uz": "Oxirgi amal yozuvi yo'q", "en": "No recorded actions"}.get(lang, "No actions")

        titles = {
            "tr": ("🔍 <b>360° İSTİHBARAT & GÜVENLİK DOSYASI</b>", "Güven Puanı", "Canlı Durum", "İtaat Hızı", "Biyolojik Saat", "Kimlik Kaydı", "Odak Noktası", "Veri Güvenliği", "Son Hareket"),
            "ru": ("🔍 <b>360° ДОСЬЕ БЕЗОПАСНОСТИ И РАЗВЕДКИ</b>", "Индекс доверия", "Онлайн-статус", "Скорость отклика", "Биоритм/Часы", "История имени", "Фокус внимания", "Безопасность данных", "Последнее действие"),
            "uz": ("🔍 <b>360° XAVFSIZLIK VA RAZVEDKA DOSYESI</b>", "Ishonch bali", "Jonli holat", "Itoat tezligi", "Bioritm/Soat", "Ism o'zgarishi", "Asosiy e'tibor", "Ma'lumot xavfsizligi", "Oxirgi amal"),
            "en": ("🔍 <b>360° SECURITY & INTELLIGENCE DOSSIER</b>", "Trust Score", "Live Status", "Response Speed", "Circadian Clock", "Identity Log", "Primary Focus", "Data Security", "Last Action")
        }.get(lang, ("🔍 <b>360° SECURITY DOSSIER</b>", "Trust Score", "Live Status", "Response Speed", "Circadian Clock", "Identity Log", "Primary Focus", "Data Security", "Last Action"))

        t_hdr, t_scr, t_liv, t_lat, t_bio, t_ali, t_tip, t_dat, t_act = titles

        # Ferah, simetrik ve mobil cihazlarda gözü yormayan şık yerleşim
        card_text = (
            f"<b>{t_hdr}</b>\n"
            "────────────────────\n"
            f"👤 <b>{escape_html(display_name)}</b> {usr_display_tag}\n"
            f"🆔 <code>{tg_id}</code> • <b>{lbl_role_prefix}:</b> {role_label}\n"
            "────────────────────\n"
            f"{score_badge} <b>{t_scr}:</b> {score_txt}\n"
            f"{live_badge} <b>{t_liv}:</b> {live_status}\n"
            f"⏱️ <b>{t_lat}:</b> {itaat_txt}\n\n"
            f"🕒 <b>{t_bio}:</b> {rutin_txt}\n"
            f"🎭 <b>{t_ali}:</b> {escape_html(alias_txt)}\n"
            f"🧠 <b>{t_tip}:</b> {persona_txt}\n"
            f"📦 <b>{t_dat}:</b> {dl_txt}{excuse_360_txt}\n"
            "────────────────────\n"
            f"👣 <b>{t_act}:</b>\n"
            f"<i>{escape_html(last_act)}</i>\n"
            "────────────────────"
        )

        btn_refresh = {"tr": "🔄 Anlık Yenile", "ru": "🔄 Обновить досье", "uz": "🔄 Yangilash", "en": "🔄 Refresh Dossier"}.get(lang, "🔄 Refresh")
        btn_kill = {"tr": "⛔ Karantina", "ru": "⛔ В изоляцию", "uz": "⛔ Karantin", "en": "⛔ Quarantine"}.get(lang, "⛔ Quarantine")
