@router.callback_query(F.data.in_(["adm:class_promotion_confirm", "adm:class_promotion_pin_prompt"]))
async def cb_admin_class_promotion_confirm(query: CallbackQuery):
    try: await query.answer()
    except Exception: pass
    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"
        if not is_admin_user(user, query.from_user.id):
            await query.answer(get_text("unauthorized_action", lang), show_alert=True)
            return

        target_chat_id = query.message.chat.id if query.message else query.from_user.id
        bot_obj = query.bot if getattr(query, 'bot', None) else (query.message.bot if query.message else bot)
        try:
            buf = await export_all_school_data_excel()
            today_str = datetime.utcnow().strftime("%d_%m_%Y")
            file = BufferedInputFile(buf.read(), filename=f"Terfi_Oncesi_Yedek_{today_str}.xlsx")
            caption = {"tr": "📦 <b>Sınıf Atlatma Öncesi Otomatik Tam Sistem Yedeği</b>", "ru": "📦 <b>Автоматический архив системы перед переводом классов</b>", "uz": "📦 <b>Sinf ko'chirishdan oldingi avtomatik to'liq tizim zaxirasi</b>", "en": "📦 <b>Pre-Promotion Automatic Full System Backup</b>"}.get(lang, "📦 <b>Automatic Pre-Promotion System Backup</b>")
            await bot_obj.send_document(chat_id=target_chat_id, document=file, caption=caption, parse_mode="HTML")
            buf.close()
        except Exception:
            pass

        students = (await session.execute(select(Student))).scalars().all()
        promoted_cnt = 0
        graduated_cnt = 0
        current_year = datetime.utcnow().year

        for s in students:
            if s.class_name.startswith("MEZUN"):
                continue
            m = re.match(r"^(\d+)(.*)$", s.class_name.strip())
            if m:
                grade_num = int(m.group(1))
                suffix = m.group(2)
                if grade_num >= 12:
                    grad = Graduate(
                        full_name=s.full_name,
                        student_number=s.student_number,
                        graduated_class=s.class_name,
                        graduation_year=current_year,
                        parent_phone=None
                    )
                    session.add(grad)
                    s.class_name = f"MEZUN-{s.class_name}"
                    graduated_cnt += 1
                else:
                    s.class_name = f"{grade_num + 1}{suffix}"
                promoted_cnt += 1

        await session.commit()

        succ_card = {
            "tr": (
                "✅ <b>TOPLU SINIF TERFİSİ BAŞARIYLA TAMAMLANDI!</b>\n"
                "────────────────────\n"
                f"• Yükseltilen Öğrenci: <b>{promoted_cnt - graduated_cnt}</b>\n"
                f"• Mezun Olan Öğrenci: <b>{graduated_cnt}</b> (Arşive eklendi)\n"
                f"• Toplam İşlem Gören: <b>{promoted_cnt}</b>\n"
                "────────────────────\n"
                "<i>Öğrenci notları ve devamsızlık kayıtları korunarak sınıflar bir üst kademeye aktarılmıştır.</i>"
            ),
            "ru": (
                "✅ <b>МАССОВЫЙ ПЕРЕВОД КЛАССОВ УСПЕШНО ЗАВЕРШЕН!</b>\n"
                "────────────────────\n"
                f"• Переведено в следующий класс: <b>{promoted_cnt - graduated_cnt}</b>\n"
                f"• Выпущено и заархивировано: <b>{graduated_cnt}</b>\n"
                f"• Всего обработано учеников: <b>{promoted_cnt}</b>\n"
                "────────────────────\n"
                "<i>Классы переведены на ступень выше с сохранением всех архивных оценок и данных.</i>"
            ),
            "uz": (
                "✅ <b>OMMAVIY SINF KO'CHIRISH MUVAFFAQIYATLI YAKUNLANDI!</b>\n"
                "────────────────────\n"
                f"• Yuqori sinfga o'tkazildi: <b>{promoted_cnt - graduated_cnt}</b>\n"
                f"• Bitiruvchilar (Arxivga olindi): <b>{graduated_cnt}</b>\n"
                f"• Jami ko'chirilganlar: <b>{promoted_cnt}</b>\n"
                "────────────────────\n"
                "<i>Barcha baholar va ma'lumotlar saqlangan holda sinflar ko'chirildi.</i>"
            ),
            "en": (
                "✅ <b>BULK CLASS PROMOTION COMPLETED SUCCESSFULLY!</b>\n"
                "────────────────────\n"
                f"• Promoted to Next Grade: <b>{promoted_cnt - graduated_cnt}</b>\n"
                f"• Graduated & Archived: <b>{graduated_cnt}</b>\n"
                f"• Total Processed Students: <b>{promoted_cnt}</b>\n"
                "────────────────────\n"
                "<i>Classes successfully advanced with all historical records preserved.</i>"
            )
        }.get(lang, "Promotion completed successfully.")

        buttons = [
            [InlineKeyboardButton(text={"tr": "🎓 Mezunlar Arşivi", "ru": "🎓 Архив выпускников", "uz": "🎓 Bitiruvchilar arxivi", "en": "🎓 Alumni Archive"}.get(lang, "🎓 Alumni"), callback_data="adm:graduates:0")],
            [InlineKeyboardButton(text=get_text("btn_classes", lang), callback_data="adm:classes")],
            get_nav_buttons(lang, back_callback="adm:class_promotion_init")
        ]
        await safe_edit_or_answer(query, succ_card, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons), parse_mode="HTML")
    await query.answer()

# --- SINIFA GÖRE TEKİL TERFİ (SEÇİMLİ SINIFA ÖZEL TERFİ) ---
@router.callback_query(F.data.startswith("adm:promo_cls_list:"))
async def cb_admin_promo_class_list(query: CallbackQuery):
    page = int(query.data.split(":")[2]) if len(query.data.split(":")) > 2 and query.data.split(":")[2].isdigit() else 0
    PAGE_SIZE = 10
    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"
        if not is_admin_user(user, query.from_user.id):
            await query.answer(get_text("unauthorized_action", lang), show_alert=True)
            return

        all_classes_raw = (await session.execute(select(Student.class_name).where(~Student.class_name.startswith("MEZUN")).distinct())).scalars().all()
        # Sort classes naturally
        def cls_sort_key(c):
            m = re.match(r"^(\d+)(.*)$", str(c).strip())
            return (int(m.group(1)), m.group(2)) if m else (999, str(c))
        
        all_classes = sorted(all_classes_raw, key=cls_sort_key)
        total = len(all_classes)
        total_pages = max(1, (total + PAGE_SIZE - 1) // PAGE_SIZE)
        page = max(0, min(page, total_pages - 1))

        buttons = []
        if total == 0:
            content = "<i>" + {"tr": "Sistemde terfi edilebilecek aktif sınıf bulunmamaktadır.", "ru": "В системе нет активных классов для перевода.", "uz": "Tizimda ko'chirish uchun faol sinflar topilmadi.", "en": "No active classes found for promotion."}.get(lang, "No classes found.") + "</i>"
        else:
            paged = all_classes[page * PAGE_SIZE : (page + 1) * PAGE_SIZE]
            row = []
            for c in paged:
                cnt = (await session.execute(select(func.count(Student.id)).where(Student.class_name == c))).scalar() or 0
                row.append(InlineKeyboardButton(text=f"🏫 {c} ({cnt})", callback_data=f"adm:promo_card:{c}"))
                if len(row) == 2:
                    buttons.append(row)
                    row = []
            if row: buttons.append(row)

            if total_pages > 1:
                nav_row = []
                if page > 0:
                    nav_row.append(InlineKeyboardButton(text=get_text("btn_prev", lang), callback_data=f"adm:promo_cls_list:{page-1}"))
                nav_row.append(InlineKeyboardButton(text=f"📄 {page+1}/{total_pages}", callback_data="noop"))
                if page < total_pages - 1:
                    nav_row.append(InlineKeyboardButton(text=get_text("btn_next", lang), callback_data=f"adm:promo_cls_list:{page+1}"))
                buttons.append(nav_row)

        buttons.append([InlineKeyboardButton(text=get_text("btn_back", lang), callback_data="adm:class_promotion_init")])

        hdr_list = {
            "tr": f"🏫 <b>SINIFA GÖRE TERFİ</b> (Toplam {total} Sınıf)\n────────────────────\nTerfi ettirmek veya mezun etmek istediğiniz sınıfı seçiniz:",
            "ru": f"🏫 <b>ПОКЛАССОВЫЙ ПЕРЕВОД</b> (Всего: {total} кл.)\n────────────────────\nВыберите класс, который необходимо перевести или выпустить:",
            "uz": f"🏫 <b>SINF BO'YICHA KO'CHIRISH</b> (Jami: {total} ta sinf)\n────────────────────\nKo'chirmoqchi yoki bitiruvchi qilmoqchi bo'lgan sinfni tanlang:",
            "en": f"🏫 <b>CLASS-BY-CLASS PROMOTION</b> (Total: {total} Classes)\n────────────────────\nSelect the class you want to promote or graduate:"
        }.get(lang, "Select class to promote:")

        await safe_edit_or_answer(query, hdr_list, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons), parse_mode="HTML")
    await query.answer()

@router.callback_query(F.data.startswith("adm:promo_card:"))
async def cb_admin_promo_class_card(query: CallbackQuery):
    class_name = query.data.split(":")[2]
    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"
        if not is_admin_user(user, query.from_user.id):
            await query.answer(get_text("unauthorized_action", lang), show_alert=True)
            return

        students_cnt = (await session.execute(select(func.count(Student.id)).where(Student.class_name == class_name))).scalar() or 0
        m = re.match(r"^(\d+)(.*)$", class_name.strip())
