@router.callback_query(F.data.startswith("adm:promo_do:"))
async def cb_admin_promo_class_do(query: CallbackQuery):
    parts = query.data.split(":")
    class_name = parts[2]
    action = parts[3]  # "next" or "graduate"

    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"
        if not is_admin_user(user, query.from_user.id):
            await query.answer(get_text("unauthorized_action", lang), show_alert=True)
            return

        target_chat_id = query.message.chat.id if query.message else query.from_user.id
        bot_obj = query.bot if getattr(query, 'bot', None) else (query.message.bot if query.message else bot)

        # 1. Send Excel backup of the school
        try:
            buf = await export_all_school_data_excel()
            today_str = datetime.utcnow().strftime("%d_%m_%Y")
            file = BufferedInputFile(buf.read(), filename=f"Terfi_Yedek_{class_name}_{today_str}.xlsx")
            caption = {"tr": f"📦 <b>{class_name} Sınıfı Terfisi Öncesi Sistem Yedeği</b>", "ru": f"📦 <b>Архив системы перед переводом класса {class_name}</b>", "uz": f"📦 <b>{class_name} sinfi ko'chirilishidan oldingi zaxira</b>", "en": f"📦 <b>Pre-Promotion System Backup for Class {class_name}</b>"}.get(lang, "📦 Backup")
            await bot_obj.send_document(chat_id=target_chat_id, document=file, caption=caption, parse_mode="HTML")
            buf.close()
        except Exception:
            pass

        students = (await session.execute(select(Student).where(Student.class_name == class_name))).scalars().all()
        m = re.match(r"^(\d+)(.*)$", class_name.strip())
        grade_num = int(m.group(1)) if m else 0
        suffix = m.group(2) if m else ""
        current_year = datetime.utcnow().year

        if action == "graduate" or (action == "next" and grade_num >= 12):
            # Graduate all students in this class
            for s in students:
                grad = Graduate(
                    full_name=s.full_name,
                    student_number=s.student_number,
                    graduated_class=class_name,
                    graduation_year=current_year,
                    parent_phone=None
                )
                session.add(grad)
                s.class_name = f"MEZUN-{class_name}"
            await session.commit()

            succ_msg = {
                "tr": (
                    f"🎓 <b>{class_name} SINIFI BAŞARIYLA MEZUN EDİLDİ!</b>\n"
                    "────────────────────\n"
                    f"• Mezun Edilen Öğrenci: <b>{len(students)}</b>\n"
                    f"• Mezuniyet Yılı: <b>{current_year}</b>\n"
                    "────────────────────\n"
                    "<i>Öğrenciler başarıyla 'Mezunlar Arşivi'ne taşınmış ve kayıt altına alınmıştır.</i>"
                ),
                "ru": (
                    f"🎓 <b>КЛАСС {class_name} УСПЕШНО ВЫПУЩЕН!</b>\n"
                    "────────────────────\n"
                    f"• Выпущено учеников: <b>{len(students)}</b>\n"
                    f"• Год выпуска: <b>{current_year}</b>\n"
                    "────────────────────\n"
                    "<i>Все выпускники успешно сохранены в Архиве выпускников.</i>"
                ),
                "uz": (
                    f"🎓 <b>{class_name} SINFI MUVAFFAQIYATLI BITIRUVCHI QILINDI!</b>\n"
                    "────────────────────\n"
                    f"• Bitirgan o'quvchilar: <b>{len(students)}</b> ta\n"
                    f"• Bitiruv yili: <b>{current_year}</b>\n"
                    "────────────────────\n"
                    "<i>O'quvchilar 'Bitiruvchilar arxivi'ga muvaffaqiyatli saqlandi.</i>"
                ),
                "en": (
                    f"🎓 <b>CLASS {class_name} GRADUATED SUCCESSFULLY!</b>\n"
                    "────────────────────\n"
                    f"• Graduated Students: <b>{len(students)}</b>\n"
                    f"• Graduation Year: <b>{current_year}</b>\n"
                    "────────────────────\n"
                    "<i>All students have been archived in the Alumni Archive.</i>"
                )
            }.get(lang, f"Class {class_name} graduated.")

        else:
            new_cls = f"{grade_num + 1}{suffix}"
            for s in students:
                s.class_name = new_cls
            
            # Also ensure ClassRoom exists or is updated
            cr_exist = (await session.execute(select(ClassRoom).where(ClassRoom.name == new_cls))).scalar_one_or_none()
            if not cr_exist:
                session.add(ClassRoom(name=new_cls))

            await session.commit()

            succ_msg = {
                "tr": (
                    f"✅ <b>SINIF TERFİSİ TAMAMLANDI!</b>\n"
                    "────────────────────\n"
                    f"🏫 <b>{class_name} ➔ {new_cls}</b>\n"
                    f"• Yükseltilen Öğrenci: <b>{len(students)}</b>\n"
                    "────────────────────\n"
                    f"<i>{class_name} sınıfındaki tüm öğrencilerin seviyesi başarıyla {new_cls} olarak güncellenmiştir.</i>"
                ),
                "ru": (
                    f"✅ <b>ПЕРЕВОД КЛАССА УСПЕШНО ЗАВЕРШЕН!</b>\n"
                    "────────────────────\n"
                    f"🏫 <b>{class_name} ➔ {new_cls}</b>\n"
                    f"• Переведено учеников: <b>{len(students)}</b>\n"
                    "────────────────────\n"
                    f"<i>Все ученики класса {class_name} успешно переведены в {new_cls}.</i>"
                ),
                "uz": (
                    f"✅ <b>SINF KO'CHIRISH YAKUNLANDI!</b>\n"
                    "────────────────────\n"
                    f"🏫 <b>{class_name} ➔ {new_cls}</b>\n"
                    f"• Ko'chirilgan o'quvchilar: <b>{len(students)}</b> ta\n"
                    "────────────────────\n"
                    f"<i>{class_name} sinfidagi barcha o'quvchilar muvaffaqiyatli {new_cls} ga o'tkazildi.</i>"
                ),
                "en": (
                    f"✅ <b>CLASS PROMOTION COMPLETED!</b>\n"
                    "────────────────────\n"
                    f"🏫 <b>{class_name} ➔ {new_cls}</b>\n"
                    f"• Promoted Students: <b>{len(students)}</b>\n"
                    "────────────────────\n"
                    f"<i>All students from class {class_name} have been advanced to {new_cls}.</i>"
                )
            }.get(lang, f"Class {class_name} promoted to {new_cls}.")

        buttons = [
            [InlineKeyboardButton(text={"tr": "🏫 Başka Bir Sınıf Seç", "ru": "🏫 Выбрать другой класс", "uz": "🏫 Boshqa sinfni tanlash", "en": "🏫 Select Another Class"}.get(lang, "Select Another Class"), callback_data="adm:promo_cls_list:0")],
            [InlineKeyboardButton(text={"tr": "🎓 Mezunlar Arşivi", "ru": "🎓 Архив выпускников", "uz": "🎓 Bitiruvchilar arxivi", "en": "🎓 Alumni Archive"}.get(lang, "Alumni Archive"), callback_data="adm:graduates:0")],
            get_nav_buttons(lang, back_callback="adm:class_promotion_init")
        ]
        await safe_edit_or_answer(query, succ_msg, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons), parse_mode="HTML")
