def match_reply_button(text: str) -> str | None:
    if not text:
        return None
    clean_text = text.strip()

    # 1. Birebir lokalizasyon eşleşmesi (tüm dillerdeki buton etiketleri)
    for key, action in REPLY_BUTTON_ACTIONS.items():
        for lang_code in LOCALES:
            btn_txt = LOCALES[lang_code].get(key, "")
            if btn_txt and btn_txt == clean_text:
                return action

    # 2. Emojisiz / Temizlenmiş tam metin eşleşmesi
    clean_norm = re.sub(r'^[^\w]+|[^\w]+$', '', clean_text).strip().lower()
    for key, action in REPLY_BUTTON_ACTIONS.items():
        for lang_code in LOCALES:
            btn_txt = LOCALES[lang_code].get(key, "")
            if btn_txt:
                norm_btn = re.sub(r'^[^\w]+|[^\w]+$', '', btn_txt).strip().lower()
                if norm_btn and norm_btn == clean_norm:
                    return action

    # 3. Bilinen standart buton tam adları (Asla kısmi alt dize araması yapılmaz!)
    exact_known_labels = {
        "ana menu": "act_main_menu",
        "ana menü": "act_main_menu",
        "baş menü": "act_main_menu",
        "главное меню": "act_main_menu",
        "главное": "act_main_menu",
        "main menu": "act_main_menu",
        "asosiy menyu": "act_main_menu",
        "menu": "act_main_menu",
        "menü": "act_main_menu",
        "kadro ve ogrenciler": "act_cat_staff",
        "kadro & ogrenci": "act_cat_staff",
        "kadro & öğrenci": "act_cat_staff",
        "персонал и дети": "act_cat_staff",
        "ученики и учителя": "act_cat_staff",
        "staff & students": "act_cat_staff",
        "xodimlar va o'quvchilar": "act_cat_staff",
        "raporlar & denetim": "act_cat_tools_reports",
        "отчеты и контроль": "act_cat_tools_reports",
        "idari araclar": "act_cat_tools_reports",
        "инструменты": "act_cat_tools_reports",
        "onay masasi": "act_cat_requests",
        "центр одобрений": "act_cat_requests",
        "sistem & ayarlar": "act_cat_settings",
        "настройки": "act_cat_settings",
        "настройки системы": "act_cat_settings",
        "cikis yap": "act_logout",
        "çıkış yap": "act_logout",
        "выйти": "act_logout",
        "log out": "act_logout",
        "chiqish": "act_logout",
    }
    return exact_known_labels.get(clean_norm, None)

