@router.callback_query(F.data == "adm:heatmap")
async def cb_admin_activity_heatmap(query: CallbackQuery):
    user_id = query.from_user.id
    async with AsyncSessionLocal() as session:
        user = await session.get(User, user_id)
        lang = user.language if user else "tr"
        if not is_admin_user(user, user_id):
            await query.answer(get_text("unauthorized_action", lang), show_alert=True)
            return

        users = (await session.execute(select(User.last_seen_at).where(User.last_seen_at.isnot(None)))).scalars().all()
        bins = {"sabah": 0, "ogle": 0, "ikindi": 0, "aksam": 0, "gece": 0}
        for dt in users:
            h = (dt.hour + TIMEZONE_OFFSET) % 24
            if 8 <= h < 12: bins["sabah"] += 1
            elif 12 <= h < 14: bins["ogle"] += 1
            elif 14 <= h < 18: bins["ikindi"] += 1
            elif 18 <= h < 22: bins["aksam"] += 1
            else: bins["gece"] += 1

        total = max(1, sum(bins.values()))
        max_v = max(1, max(bins.values()))

        def get_bar(val):
            return render_progress_bar(int(round(val * 10 / max_v)), 10)

        hdr = {
            "tr": "📊 <b>CANLI KULLANICI ETKİLEŞİM ISI HARİTASI</b>",
            "ru": "📊 <b>ТЕПЛОВАЯ КАРТА АКТИВНОСТИ ПОЛЬЗОВАТЕЛЕЙ</b>",
            "uz": "📊 <b>FOYDALANUVCHILAR FAOLLIGI ISSIQLIK XARITASI</b>",
            "en": "📊 <b>LIVE USER ACTIVITY HEATMAP</b>"
        }.get(lang, "📊 <b>ACTIVITY HEATMAP</b>")

        labels = {
            "tr": ("🌅 Sabah (08:00 - 12:00)", "☀️ Öğle (12:00 - 14:00)", "🌇 İkindi (14:00 - 18:00)", "🌙 Akşam (18:00 - 22:00)", "🦉 Gece (22:00 - 08:00)"),
            "ru": ("🌅 Утро (08:00 - 12:00)", "☀️ Обед (12:00 - 14:00)", "🌇 День (14:00 - 18:00)", "🌙 Вечер (18:00 - 22:00)", "🦉 Ночь (22:00 - 08:00)"),
            "uz": ("🌅 Tong (08:00 - 12:00)", "☀️ Tush (12:00 - 14:00)", "🌇 Peshin (14:00 - 18:00)", "🌙 Oqshom (18:00 - 22:00)", "🦉 Tun (22:00 - 08:00)"),
            "en": ("🌅 Morning (08:00 - 12:00)", "☀️ Noon (12:00 - 14:00)", "🌇 Afternoon (14:00 - 18:00)", "🌙 Evening (18:00 - 22:00)", "🦉 Night (22:00 - 08:00)")
        }.get(lang, ("Morning", "Noon", "Afternoon", "Evening", "Night"))

        pct_s = round(bins["sabah"] * 100 / total, 1)
        pct_o = round(bins["ogle"] * 100 / total, 1)
        pct_i = round(bins["ikindi"] * 100 / total, 1)
        pct_a = round(bins["aksam"] * 100 / total, 1)
        pct_g = round(bins["gece"] * 100 / total, 1)

        lbl_ops = {"tr": "işlem", "ru": "действий", "uz": "amal", "en": "actions"}.get(lang, "actions")
        lbl_tot_act = {"tr": "Toplam Kayıtlı Aktivite", "ru": "Всего зафиксировано активности", "uz": "Jami qayd etilgan faollik", "en": "Total Recorded Activity"}.get(lang, "Total Activity")

        text = (
            f"{hdr}\n"
            "────────────────────\n"
            f"{labels[0]}: <b>%{pct_s}</b>\n<code>{get_bar(bins['sabah'])}</code> ({bins['sabah']} {lbl_ops})\n\n"
            f"{labels[1]}: <b>%{pct_o}</b>\n<code>{get_bar(bins['ogle'])}</code> ({bins['ogle']} {lbl_ops})\n\n"
            f"{labels[2]}: <b>%{pct_i}</b>\n<code>{get_bar(bins['ikindi'])}</code> ({bins['ikindi']} {lbl_ops})\n\n"
            f"{labels[3]}: <b>%{pct_a}</b>\n<code>{get_bar(bins['aksam'])}</code> ({bins['aksam']} {lbl_ops})\n\n"
            f"{labels[4]}: <b>%{pct_g}</b>\n<code>{get_bar(bins['gece'])}</code> ({bins['gece']} {lbl_ops})\n"
            "────────────────────\n"
            f"👥 <b>{lbl_tot_act}:</b> {sum(bins.values())} {lbl_ops}\n"
            "────────────────────"
        )
        buttons = [get_nav_buttons(lang, back_callback="adm:cat_tools_reports")]
        await safe_edit_or_answer(query, text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons), parse_mode="HTML")
        await query.answer()


@router.callback_query(F.data == "adm:watchlist")
async def cb_admin_watchlist_hub(query: CallbackQuery):
    user_id = query.from_user.id
    async with AsyncSessionLocal() as session:
        user = await session.get(User, user_id)
        lang = user.language if user else "tr"
        if not is_admin_user(user, user_id):
            await query.answer(get_text("unauthorized_action", lang), show_alert=True)
            return

        stmt = select(User).where(
            (User.is_blacklisted == True) |
            (User.night_activity_count > 0) |
            (User.download_count >= 5) |
            (User.is_bot_blocked == True)
        ).limit(15)
        suspicious = (await session.execute(stmt)).scalars().all()

        hdr = {
            "tr": "👁️ <b>ŞÜPHELİ HESAPLAR İZLEME MASASI (WATCHLIST)</b>",
            "ru": "👁️ <b>СПИСОК НАБЛЮДЕНИЯ ЗА ПОДОЗРИТЕЛЬНЫМИ</b>",
            "uz": "👁️ <b>GUMONLI HISOB-KITOBLAR KUZATUV STOLI</b>",
            "en": "👁️ <b>SECURITY WATCHLIST HUB</b>"
        }.get(lang, "👁️ <b>WATCHLIST</b>")

        buttons = []
        if not suspicious:
            text = (
                f"{hdr}\n"
                "────────────────────\n"
                f"<i>" + {"tr": "Şu anda şüpheli hareket sergileyen veya radar listesine giren kullanıcı bulunmamaktadır.", "ru": "В настоящее время нет подозрительных пользователей в списке.", "uz": "Hozirda shubhali foydalanuvchilar mavjud emas.", "en": "No suspicious users currently on the watchlist."}.get(lang, "No suspicious users.") + "</i>\n"
                "────────────────────"
            )
        else:
            lines = [f"{hdr}\n────────────────────\n" + {"tr": "Güvenlik radarına takılan (gece işlemi, engelleme, yüksek indirme) hesaplar:", "ru": "Пользователи, попавшие под радар безопасности:", "uz": "Xavfsizlik radariga tushgan foydalanuvchilar:", "en": "Accounts flagged by security radar:"}.get(lang, "Flagged accounts:") + "\n"]
            lbl_banned = {"tr": "Yasaklı", "ru": "Заблокирован", "uz": "Bloklangan", "en": "Banned"}.get(lang, "Banned")
            lbl_blocked_bot = {"tr": "Botu Sildi", "ru": "Удалил бота", "uz": "Botni o'chirdi", "en": "Removed Bot"}.get(lang, "Blocked Bot")
            lbl_night = {"tr": "Gece", "ru": "Ночь", "uz": "Tun", "en": "Night"}.get(lang, "Night")
            lbl_downloads = {"tr": "İndirme", "ru": "Загрузок", "uz": "Yuklab olish", "en": "Downloads"}.get(lang, "Downloads")
            lbl_u_def = {"tr": "Kullanıcı", "ru": "Пользователь", "uz": "Foydalanuvchi", "en": "User"}.get(lang, "User")

            for u in suspicious:
                flags = []
                if u.is_blacklisted: flags.append(lbl_banned)
                if u.is_bot_blocked: flags.append(lbl_blocked_bot)
                if u.night_activity_count > 0: flags.append(f"{u.night_activity_count} {lbl_night}")
                if u.download_count >= 5: flags.append(f"{u.download_count} {lbl_downloads}")
                f_str = ", ".join(flags)

                badge = "🔴" if u.is_blacklisted or u.is_bot_blocked else "🟡"
                u_name = u.full_name or lbl_u_def
                lines.append(f"{badge} <b>{escape_html(u_name)}</b> (<code>{u.telegram_id}</code>)\n   ↳ <i>{f_str}</i>")
                buttons.append([InlineKeyboardButton(text=f"{badge} {u_name} ({f_str[:16]})", callback_data=f"adm:user_360:{u.telegram_id}:0")])
            lines.append("────────────────────")
            text = "\n".join(lines)

        buttons.append(get_nav_buttons(lang, back_callback="adm:cat_tools_reports"))
        await safe_edit_or_answer(query, text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons), parse_mode="HTML")
        await query.answer()

