            content = "<i>" + {"tr": "Sistemde henüz arşivlenmiş mezun öğrenci bulunmamaktadır.", "ru": "В архиве пока нет выпускников.", "uz": "Arxivda hali bitiruvchilar mavjud emas.", "en": "No archived graduates found in the system."}.get(lang, "No graduates.") + "</i>"
