        buttons.append([InlineKeyboardButton(text=b_promo_hub, callback_data="adm:class_promotion_init")])
        buttons.append(get_nav_buttons(lang, back_callback="adm:cat_staff"))

        footer_ga = {"tr": "ℹ️ <i>Sınıf terfi işlemlerinde son sınıftan mezun olan öğrenciler otomatik olarak buraya arşivlenir.</i>", "ru": "ℹ️ <i>При переводе классов выпускники старших классов автоматически архивируются в этом разделе.</i>", "uz": "ℹ️ <i>Sinf ko'chirish amallarida bitiruvchilar avtomatik ravishda ushbu arxivga kiritiladi.</i>", "en": "ℹ️ <i>Graduating students are automatically archived into this directory.</i>"}.get(lang, "")

