@router.callback_query(F.data == "adm:export_graduates_excel")
async def cb_admin_export_graduates_excel(query: CallbackQuery):
    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"
        if not is_admin_user(user, query.from_user.id):
            await query.answer(get_text("unauthorized_action", lang), show_alert=True)
            return

        all_grads = (await session.execute(select(Graduate).order_by(Graduate.graduation_year.desc(), Graduate.full_name))).scalars().all()
        if not all_grads:
            no_g_tst = {"tr": "İndirilecek mezun kaydı bulunamadı.", "ru": "Нет записей выпускников для скачивания.", "uz": "Yuklab olish uchun bitiruvchilar topilmadi.", "en": "No graduate records found to download."}.get(lang, "No graduates found.")
            await query.answer(no_g_tst, show_alert=True)
            return

        wb = openpyxl.Workbook()
        ws = wb.active
        ws.title = "Mezunlar"

        headers = [
            {"tr": "ID", "ru": "ID", "uz": "ID", "en": "ID"}.get(lang, "ID"),
            {"tr": "Ad Soyad", "ru": "ФИО", "uz": "F.I.O", "en": "Full Name"}.get(lang, "Name"),
            {"tr": "Mezun Olduğu Sınıf", "ru": "Класс выпуска", "uz": "Bitirgan sinfi", "en": "Graduated Class"}.get(lang, "Class"),
            {"tr": "Okul Numarası", "ru": "Номер в школе", "uz": "Maktab raqami", "en": "Student Number"}.get(lang, "Number"),
            {"tr": "Mezuniyet Yılı", "ru": "Год выпуска", "uz": "Bitirgan yili", "en": "Graduation Year"}.get(lang, "Year"),
            {"tr": "Kayıt Tarihi", "ru": "Дата архивации", "uz": "Arxivlangan sana", "en": "Archived Date"}.get(lang, "Date")
        ]
        ws.append(headers)

        header_fill = openpyxl.styles.PatternFill(start_color="1F4E79", end_color="1F4E79", fill_type="solid")
        header_font = openpyxl.styles.Font(name="Calibri", size=11, bold=True, color="FFFFFF")

        for col_idx in range(1, len(headers) + 1):
            cell = ws.cell(row=1, column=col_idx)
            cell.fill = header_fill
            cell.font = header_font
            cell.alignment = openpyxl.styles.Alignment(horizontal="center", vertical="center")

        for g in all_grads:
            d_str = (g.created_at + timedelta(hours=TIMEZONE_OFFSET)).strftime("%d.%m.%Y %H:%M") if g.created_at else "-"
            ws.append([g.id, g.full_name, g.graduated_class, g.student_number, g.graduation_year, d_str])

        for col in ws.columns:
            max_len = max(len(str(cell.value or '')) for cell in col)
            col_letter = openpyxl.utils.get_column_letter(col[0].column)
            ws.column_dimensions[col_letter].width = min(40, max(12, max_len + 3))

        bio = io.BytesIO()
        wb.save(bio)
        bio.seek(0)

        file = BufferedInputFile(bio.read(), filename=f"Mezunlar_Arsivi_{datetime.utcnow().strftime('%Y%m%d')}.xlsx")
        cap = {
            "tr": f"🎓 <b>Mezunlar Arşivi Resmi Excel Listesi</b> (Toplam {len(all_grads)} Mezun)",
            "ru": f"🎓 <b>Официальный список выпускников (Excel)</b> (Всего: {len(all_grads)} вып.)",
            "uz": f"🎓 <b>Bitiruvchilar rasmiy ro'yxati (Excel)</b> (Jami: {len(all_grads)} ta)",
            "en": f"🎓 <b>Official Graduates & Alumni Excel Sheet</b> (Total: {len(all_grads)} Graduates)"
        }.get(lang, "Graduates Excel")

        target_chat_id = query.message.chat.id if query.message else query.from_user.id
        bot_obj = query.bot if getattr(query, 'bot', None) else (query.message.bot if query.message else bot)
        await bot_obj.send_document(chat_id=target_chat_id, document=file, caption=cap, parse_mode="HTML")
        bio.close()
        await query.answer({"tr": "✅ Excel aktarıldı!", "ru": "✅ Файл отправлен!", "uz": "✅ Fayl yuborildi!", "en": "✅ File sent!"}.get(lang, "✅ Sent!"), show_alert=False)

@router.callback_query(F.data.startswith("adm:remind_votes:"))
async def cb_admin_remind_votes(query: CallbackQuery):
    prop_id = int(query.data.split(":")[2])
    async with AsyncSessionLocal() as session:
        user = await session.get(User, query.from_user.id)
        lang = user.language if user else "tr"
        if not is_admin_user(user, query.from_user.id):

            await query.answer(get_text("unauthorized_action", lang), show_alert=True)

            return

        prop = await session.get(Proposal, prop_id)
        if not prop or prop.status != "active":
            await query.answer({"tr": "⚠️ Bu oylama aktif değil!", "ru": "⚠️ Это голосование уже не активно!", "uz": "⚠️ Ushbu ovoz berish faol emas!", "en": "⚠️ This ballot is not active!"}.get(lang, "⚠️ Inactive ballot!"), show_alert=True)
            return

        voted_user_ids = set((await session.execute(select(ProposalVote.user_telegram_id).where(ProposalVote.proposal_id == prop_id))).scalars().all())

        target_uids = []
        if prop.target_audience == "teachers":
            target_uids = (await session.execute(select(User.telegram_id).where(User.role == "teacher"))).scalars().all()
        elif prop.target_audience == "admins":
            target_uids = (await session.execute(select(User.telegram_id).where(User.role == "admin"))).scalars().all()
        else:
            target_uids = (await session.execute(select(User.telegram_id).where(User.role.in_(["teacher", "admin"])))).scalars().all()

        non_voters = [uid for uid in set(target_uids) if uid not in voted_user_ids]
        sent_c = 0
        u_lang_map = {u.telegram_id: (u.language or "tr") for u in (await session.execute(select(User).where(User.telegram_id.in_(non_voters)))).scalars().all()}
        for uid in non_voters:
            u_l = u_lang_map.get(uid, "tr")
            remind_txt = {
                "tr": (
                    f"🗳️ <b>OYLAMA HATIRLATMASI</b>\n"
                    "────────────────────\n"
                    f"Henüz oyunuzu kullanmadığınız bir istişare/teklif bulunmaktadır:\n\n"
                    f"📌 <b>{escape_html(prop.title)}</b>\n\n"
                    "<i>Lütfen aşağıdaki butona dokunarak görüşünüzü bildiriniz.</i>"
                ),
                "ru": (
                    f"🗳️ <b>НАПОМИНАНИЕ О ГОЛОСОВАНИИ</b>\n"
                    "────────────────────\n"
                    f"У вас есть непроголосованное обсуждение / предложение:\n\n"
                    f"📌 <b>{escape_html(prop.title)}</b>\n\n"
                    "<i>Пожалуйста, нажмите кнопку ниже, чтобы выразить свое мнение.</i>"
                ),
                "uz": (
                    f"🗳️ <b>OVOZ BERISH ESLATMASI</b>\n"
                    "────────────────────\n"
                    f"Siz hali ovoz bermagan taklif / muhokama mavjud:\n\n"
                    f"📌 <b>{escape_html(prop.title)}</b>\n\n"
                    "<i>Iltimos, quyidagi tugmani bosib o'z fikringizni bildiring.</i>"
                ),
                "en": (
                    f"🗳️ <b>BALLOT REMINDER</b>\n"
                    "────────────────────\n"
                    f"You have a pending ballot / proposal to vote on:\n\n"
                    f"📌 <b>{escape_html(prop.title)}</b>\n\n"
                    "<i>Please tap the button below to cast your vote.</i>"
                )
            }.get(u_l, f"Vote reminder: {prop.title}")

            b_open_v = {"tr": "🗳️ Oylamayı Aç ve Oy Ver", "ru": "🗳️ Открыть и проголосовать", "uz": "🗳️ Ovoz berishga o'tish", "en": "🗳️ Open & Vote"}.get(u_l, "🗳️ Open & Vote")
            vote_btn = InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text=b_open_v, callback_data=f"prop:open:{prop.id}")]
            ])
            try:
                await query.bot.send_message(chat_id=uid, text=remind_txt, reply_markup=vote_btn, parse_mode="HTML")
                sent_c += 1
                await asyncio.sleep(0.04)
            except Exception:
                pass

        tst = f"📢 {sent_c} personele oylama hatırlatması iletildi!"
